const PACKAGE={"id":"BFSdual_LF06_Lernpfad_LS6_8","ls":"6.8","title":"Lernpfadübung · LS 6.8 · Über die Fortführung der Aktion entscheiden","version":"1.1","source":"Fachbereiche/BFSdual/LF06/LS_6_8_Folgeaktion_entscheiden.md"};
const COMP=[["Fachkompetenz","Ich vergleiche die Absatzzahlen und die Kundenrückmeldungen der beiden Läden. Ich prüfe, ob sie das Ziel erreicht haben. Ich begründe, was die Läden bei Sortiment, Platzierung und Werbung ändern oder beibehalten sollten."],["Personalkompetenz","Ich erkläre, was die Daten über meine Empfehlung aussagen und was offen bleibt."],["Sozialkompetenz","Ich beachte, was beiden Läden wichtig ist. Ich begründe eine gemeinsame Entscheidung."],["Methodenkompetenz","Ich vergleiche die Absatzmengen mit der Vergleichswoche. Ich prüfe, ob das Ergebnis zum Zielwert passt."],["Medienkompetenz","Ich stelle wichtige Zahlen und Rückmeldungen übersichtlich zusammen."]];
const BANK=[{"title":"Die Läden wollen eine Antwort","scene":"Zwei Geschäfte melden sich nach der Frühjahrsaktion bei Global Bike.","ask":"Welche Aussagen geben ihre Wünsche richtig wieder?","options":["Die Bike Arena möchte einen nächsten Termin festlegen.","Block möchte seine Fläche für andere Aktionen fest vergeben.","Block würde die Fläche wieder freihalten, möchte aber vorher etwas ändern.","Die Bike Arena möchte erst nach einer Standortbesichtigung eine Entscheidung treffen.","Nur Block bittet ausdrücklich um eine Antwort.","Beide Läden erwarten bis Freitag eine Antwort."],"answer":[0,2,5],"why":"Die Bike Arena möchte den nächsten Termin festlegen. Block hält die Fläche frei und möchte vor der Zusage etwas ändern. Beide erwarten bis Freitag eine Antwort.","hint":"Ordne zuerst jede Nachricht dem passenden Laden zu und suche den gemeinsamen Termin.","steps":"Ordne die Aussagen den Beteiligten zu. Prüfe, welche Rolle und welche Aufgabe jeweils gemeint sind.","example":"Zwei Läden können dieselbe Aktion fortsetzen und trotzdem unterschiedliche Änderungen benötigen.","c":2,"sourceRefs":["Handlungssituation"],"id":0,"l":1,"type":"multi","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Christians Ziel","scene":"Christian prüft den Aktionsbericht, bevor Jan die nächste Aktion empfiehlt.","ask":"Was genau wollte Global Bike erreichen?","options":["Zusammen sollten beide Läden 20 Stück mehr verkaufen.","Jeder Laden sollte mindestens 20 € mehr Umsatz pro Tag erreichen.","Jeder Laden sollte gegenüber seiner Vergleichswoche mindestens 20 % mehr Stück verkaufen.","Die Bike Arena sollte 20 % mehr Stück als Block verkaufen.","Mindestens 20 % aller Verkäufe sollten auf lokale Zusatzartikel entfallen.","Das Ziel war erreicht, sobald einer der beiden Läden 20 % mehr Stück verkaufte."],"answer":[2],"why":"Beide Standorte sollten jeweils mindestens 20 % mehr Stück aus dem Aktionssortiment verkaufen. Bezugswert ist die eigene Vergleichswoche.","hint":"Achte auf den Vergleichszeitraum, die Grenze und die Einheit.","steps":"Lies die Angaben zum Laden. Prüfe für jede Aussage, ob sie durch die Situation oder das genannte Material gedeckt ist.","example":"Eine Rückmeldung zu einer fehlenden Produktangabe kann eine Änderung der Produktkarte begründen.","c":0,"sourceRefs":["Handlungssituation","M1"],"id":1,"l":1,"type":"multi","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Was „Absatzmenge“ bedeutet","scene":"Die Bike Arena hat in der Aktionswoche 22 Minipumpen P50 verkauft.","ask":"Was bedeutet die Zahl 22 in der Tabelle?","options":["22 Kundinnen und Kunden fragten nach einer Minipumpe.","Die Minipumpen brachten 22 € Umsatz.","22 Minipumpen lagen am ersten Tag auf der Gondel.","22 Minipumpen wurden zusätzlich zur Vergleichswoche verkauft.","22 Minipumpen wurden in der Aktionswoche verkauft.","Global Bike hatte in beiden Läden zusammen 22 Minipumpen im Aktionsbestand."],"answer":[4],"why":"Absatzmengen sind verkaufte Stück. Die Zahl 22 erfasst die verkauften Minipumpen P50 in der Aktionswoche der Bike Arena.","hint":"Lies die Überschrift von M2 und unterscheide die Einheit Stück vom Umsatz in Euro.","steps":"Lies die Angaben zum Laden. Prüfe für jede Aussage, ob sie durch die Situation oder das genannte Material gedeckt ist.","example":"Eine Rückmeldung zu einer fehlenden Produktangabe kann eine Änderung der Produktkarte begründen.","c":0,"sourceRefs":["M2","M6"],"id":2,"l":1,"type":"multi","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Die Vergleichswoche richtig lesen","scene":"Beide Läden waren in beiden Wochen je fünf Tage geöffnet. Alle Aktionsartikel waren lieferbar.","ask":"Welche Regeln gelten beim Vergleich?","options":["Die Bike Arena ist die Vergleichswoche für Block.","Verglichen werden für jeden Laden seine eigenen Stückzahlen.","Leere Felder bedeuten, dass der Artikel in dieser Woche ausverkauft war.","Die beiden verglichenen Wochen umfassen in jedem Laden jeweils fünf Öffnungstage.","Allein das gleich lange Zeitfenster beweist die Wirkung einer Werbemaßnahme.","Ein leeres Feld kennzeichnet einen Artikel außerhalb des jeweiligen Aktionssortiments."],"answer":[1,3,5],"why":"Jeder Laden wird mit sich selbst verglichen. Gleiche Öffnungstage machen die Zeiträume besser vergleichbar. Leere Felder bedeuten, dass der Artikel im betreffenden Laden nicht zur Aktion gehört.","hint":"Prüfe, welche Woche zu welchem Laden gehört und was die Tabelle zu leeren Feldern erklärt.","steps":"Halte die Angaben aus der Aufgabe getrennt fest. Vergleiche dann jede Auswahl mit diesen Angaben und dem gefragten Kriterium.","example":"Beispiel: Von 20 auf 22 Stück sind es 2 Stück mehr. Bezogen auf 20 Stück entspricht das 10 %.","c":3,"sourceRefs":["M1","M2","M5"],"id":3,"l":1,"type":"multi","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Prozentänderung berechnen","scene":"Übungsvariante: Ein Laden verkauft in einer Vergleichswoche 20 Stück. In der Aktionswoche sind es 22.","ask":"Welche Rechenschritte liefern die prozentuale Absatzveränderung?","options":["Aktionsmenge minus Vergleichsmenge ergibt den Unterschied in Stück.","Die Differenz wird durch die Aktionsmenge geteilt, weil sie neuer ist.","Die Aktionsmenge wird durch 100 geteilt und direkt als Prozentwert ausgegeben.","Die Vergleichsmenge minus die Aktionsmenge zeigt die Zunahme.","Die Differenz wird durch die Vergleichsmenge geteilt und mit 100 multipliziert.","Die beiden Wochenmengen werden addiert, bevor man den Prozentwert berechnet."],"answer":[0,4],"why":"Zieht zuerst 20 von 22 ab. Teilt die 2 zusätzlichen Stück durch den alten Wert 20 und multipliziert mit 100. Das Ergebnis ist +10 %.","hint":"Überlege, welche Stückzahl am Anfang den Bezugspunkt bildet.","steps":"Halte die Angaben aus der Aufgabe getrennt fest. Vergleiche dann jede Auswahl mit diesen Angaben und dem gefragten Kriterium.","example":"Beispiel: Von 20 auf 22 Stück sind es 2 Stück mehr. Bezogen auf 20 Stück entspricht das 10 %.","c":3,"sourceRefs":["M5","M6"],"id":4,"l":1,"type":"multi","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Kernsortiment und Ergänzungen","scene":"Die Frühjahrsaktion verbindet ein gemeinsames Angebot mit Artikeln für den jeweiligen Laden.","ask":"Welche Aussagen passen zum Aktionsbericht?","options":["Der Flaschenhalter F60 ist in beiden Läden Teil des Kernsortiments.","Die Minipumpe P50 gehört in beiden Läden zum Kernsortiment.","Block ergänzt die Aktion um den Sattelüberzug R40.","Die Bike Arena ergänzt die Aktion um die Minipumpe P50.","Die Bike Arena ergänzt die Aktion um F60 und B80.","Das Kernsortiment umfasst alle normalen Waren eines Ladens."],"answer":[1,2,4],"why":"Die P50 ist Teil des gemeinsamen Kernsortiments. Block führt zusätzlich R40. Die Bike Arena führt zusätzlich F60 und B80.","hint":"Achte darauf, welche Produkte in beiden Spalten stehen und welche nur einmal auftauchen.","steps":"Lies die Angaben zum Laden. Prüfe für jede Aussage, ob sie durch die Situation oder das genannte Material gedeckt ist.","example":"Eine Rückmeldung zu einer fehlenden Produktangabe kann eine Änderung der Produktkarte begründen.","c":0,"sourceRefs":["M1"],"id":5,"l":1,"type":"multi","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Maßnahmen für die beiden Läden","scene":"Der Bericht fasst zusammen, wie die Läden ihre Kundschaft auf die Aktion aufmerksam machten.","ask":"Welche Zuordnungen stimmen?","options":["Block stellte eine unbetreute Beratungsgondel direkt ans Eingangsschild.","Block lud mit einem Newsletter zur Beratung ein.","Die Bike Arena verschickte einen Newsletter zur Vorführung.","In beiden Läden fand die Vorführung am Beratungsplatz statt.","Das Eingangsschild war Blocks wichtigste Werbemaßnahme.","Die Bike Arena zeigte Zubehör auf zwei Aktionsgondeln mit Produktkarten."],"answer":[1,5],"why":"Bei Block lud der Newsletter zur Beratung ein. Die Bike Arena nutzte ein Eingangsschild und zwei Aktionsgondeln mit Produktkarten zur Selbstbedienung.","hint":"Beachte für jeden Laden je eine Werbemaßnahme und eine Platzierung.","steps":"Lies den Wortlaut genau. Prüfe, ob die Aussage für die betreffende Person oder den betreffenden Laden eindeutig ist.","example":"„75 Stück in der Aktionswoche“ und „plus 15 Stück“ bedeuten Verschiedenes. Eine gute Tabelle beschriftet beide Angaben.","c":4,"sourceRefs":["M1"],"id":6,"l":1,"type":"multi","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Vorschläge einordnen","scene":"Jan braucht für jeden Laden Vorschläge zu Sortiment, Platzierung und Werbung.","ask":"Welche Zuordnungen sind fachlich richtig?","options":["Sortiment: R40 im Angebot behalten oder ersetzen.","Platzierung: Den Versandtag des Newsletters ändern.","Platzierung: Den Sattelüberzug aus dem Kassenbereich an ein Zubehörregal legen.","Werbung: Den Newsletter wieder einsetzen.","Werbung: Die Liste der Aktionsartikel im Lager ändern.","Sortiment: Die Aktionsgondel an eine besser sichtbare Stelle schieben."],"answer":[0,2,3],"why":"Die Auswahl der Artikel ist Sortiment. Der Platz im Laden ist Platzierung. Der Newsletter ist ein Werbemittel.","hint":"Bestimme, ob die Aussage das Angebot, den Ort im Laden oder die Ansprache beschreibt.","steps":"Lies die Angaben zum Laden. Prüfe für jede Aussage, ob sie durch die Situation oder das genannte Material gedeckt ist.","example":"Eine Rückmeldung zu einer fehlenden Produktangabe kann eine Änderung der Produktkarte begründen.","c":0,"sourceRefs":["Handlungssituation","M4","M5"],"id":7,"l":1,"type":"multi","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Was eine Kundenstimme aussagt","scene":"Eine Person bei Block sagt, dass sie wegen der angekündigten Lichtvorführung gekommen sei.","ask":"Welche Folgerungen sind begründet?","options":["Alle Besucherinnen und Besucher kamen wegen der Lichtvorführung.","Die Person nennt die Einladung im Newsletter als Grund für ihren Besuch.","Der Satz zeigt, um wie viel Prozent der Absatz gestiegen ist.","Die Rückmeldung kann dafür sprechen, die Einladung zur Vorführung beizubehalten.","Die Rückmeldung beweist, dass der Absatz ohne Newsletter gefallen wäre.","Mit dieser Aussage ist die Zielerreichung bei Block belegt."],"answer":[1,3],"why":"Das ist eine konkrete Rückmeldung zu einem Besuch. Sie hilft bei der Entscheidung über den Newsletter, lässt die Wirkung bei anderen Personen aber offen.","hint":"Frage dich, wer die Aussage macht und für wen sie gilt.","steps":"Schreibe kurz auf, was feststeht. Markiere danach Aussagen, die eine Vermutung mit einem Befund verwechseln.","example":"Ein höherer Absatz in einer Aktionswoche zeigt eine Veränderung. Für die Ursache braucht ihr weitere Informationen.","c":1,"sourceRefs":["M3"],"id":8,"l":1,"type":"multi","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Sebastian und Christian abgleichen","scene":"Sebastian will schnell zusagen. Christian möchte vorher in den Aktionsbericht schauen.","ask":"Welche Aussagen passen?","options":["Sebastian sieht das Risiko, dass die Läden ihre Flächen für etwas anderes nutzen.","Sebastian hat den Preis der Folgeaktion bereits zugesagt.","Christian möchte Änderungen allein aus den Kundenstimmen ableiten.","Christian prüft die Zielerreichung und danach mögliche Verbesserungen anhand der Rückmeldungen.","Christian vergleicht ausschließlich, welcher Laden mehr Stück verkauft.","Jan möchte erst nach der nächsten Aktionswoche entscheiden."],"answer":[0,3],"why":"Sebastian befürchtet, dass die Läden ihre Flächen anderweitig vergeben. Christian prüft Zielwerte und Kundenrückmeldungen.","hint":"Welche Folge befürchtet Sebastian? Welche Belege braucht Christian?","steps":"Ordne die Aussagen den Beteiligten zu. Prüfe, welche Rolle und welche Aufgabe jeweils gemeint sind.","example":"Zwei Läden können dieselbe Aktion fortsetzen und trotzdem unterschiedliche Änderungen benötigen.","c":2,"sourceRefs":["Handlungssituation"],"id":9,"l":1,"type":"multi","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Zahlen lesbar darstellen","scene":"Ihr stellt die Ergebnisse in einer Tabelle für Jan und die Läden zusammen.","ask":"Welche Spalten helfen bei der Entscheidung?","options":["Vergleichswoche und Aktionswoche getrennt, mit der Einheit Stück","Ein Eurobetrag in der Spalte, die mit Absatzmenge überschrieben ist","Eine gemeinsame Summe beider Läden anstelle der Standortwerte","Ein Prozentwert ohne Erklärung des Zeitraums","Prozentuale Veränderung je Laden gegenüber der Vergleichswoche","Ziel erreicht: je Laden „Ja“ oder „Nein“"],"answer":[0,4,5],"why":"Vorher und nachher brauchen klar beschriftete Stückzahlen. Dazu gehören prozentuale Veränderung und ein sichtbares Urteil am Zielwert.","hint":"Eine Person sollte ohne Rückfrage erkennen können, wie das Ergebnis zustande kommt.","steps":"Lies den Wortlaut genau. Prüfe, ob die Aussage für die betreffende Person oder den betreffenden Laden eindeutig ist.","example":"„75 Stück in der Aktionswoche“ und „plus 15 Stück“ bedeuten Verschiedenes. Eine gute Tabelle beschriftet beide Angaben.","c":4,"sourceRefs":["M2","M5"],"id":10,"l":1,"type":"multi","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Eine Empfehlung begrenzen","scene":"In der Bike Arena fehlte einer Person beim Vergleich der Rahmentaschen die Angabe zur Rahmengröße. Ihr möchtet die Angabe auf der Produktkarte ergänzen.","ask":"Was könnt ihr mit dieser Rückmeldung begründen? Was bleibt offen?","options":["Aus der Rückmeldung folgt, dass die Mehrheit der Kundschaft die Angabe vermisste.","Die Rückmeldung stützt eine konkrete Ergänzung auf der Produktkarte.","Die Rückmeldung zeigt, um wie viel Prozent der Verkauf nach der Änderung steigen wird.","Die Rückmeldung erklärt, warum die Pumpe häufiger verkauft wurde.","Ob die geänderte Karte den Absatz erhöht, bleibt offen.","Die Rückmeldung beweist, dass die Rahmentasche aus dem Aktionssortiment gestrichen werden muss."],"answer":[1,4],"why":"Der Wunsch nach einer Größenangabe begründet die Ergänzung auf der Produktkarte. Ob die Angabe zu mehr Verkäufen führt und wie vielen Menschen sie hilft, müsste erst geprüft werden.","hint":"Trenne den Grund für die Änderung von einer Vorhersage über ihre Wirkung.","steps":"Schreibe kurz auf, was feststeht. Markiere danach Aussagen, die eine Vermutung mit einem Befund verwechseln.","example":"Ein höherer Absatz in einer Aktionswoche zeigt eine Veränderung. Für die Ursache braucht ihr weitere Informationen.","c":1,"sourceRefs":["M3","M5","M6"],"id":11,"l":1,"type":"multi","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Block: Summe der Vergleichswoche","scene":"In Block wurden vorher 12 Lichtsets, 10 Schlösser, 8 Rahmentaschen, 5 Minipumpen und 5 Sattelüberzüge verkauft.","ask":"Welche Angaben belegen den Eintrag „Stück vorher“?","options":["35 Stück aus dem Aktionssortiment","40 € Umsatz aus dem Aktionssortiment","46 Stück in der Vergleichswoche","40 Stück aus dem Aktionssortiment","5 Stück aus dem Aktionssortiment","Der Zusatzartikel R40 zählt mit fünf Stück zur Summe."],"answer":[3,5],"why":"Für Block zählen die vier gemeinsamen Artikel und R40. 12 + 10 + 8 + 5 + 5 ergibt 40 verkaufte Stück.","hint":"Addiere alle fünf Zahlen dieser einen Spalte.","steps":"Halte die Angaben aus der Aufgabe getrennt fest. Vergleiche dann jede Auswahl mit diesen Angaben und dem gefragten Kriterium.","example":"Beispiel: Von 20 auf 22 Stück sind es 2 Stück mehr. Bezogen auf 20 Stück entspricht das 10 %.","c":3,"sourceRefs":["M1","M2","M5"],"id":12,"l":2,"type":"multi","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Block: Veränderung und Ziel","scene":"Bei Block wurden 40 Stück in der Vergleichswoche und 46 in der Aktionswoche verkauft. Ziel waren mindestens 20 % Zuwachs.","ask":"Welche Aussagen treffen zu?","options":["Block verkaufte 6 % mehr Stück.","Block verkaufte 6 Stück mehr.","Block steigerte den Absatz um rund 13 %.","Block steigerte den Absatz um 15 %.","Block erreichte das Ziel, weil die Aktionswoche mehr Verkäufe brachte.","Blocks Zuwachs lag 5 Prozentpunkte unter dem Zielwert."],"answer":[1,3,5],"why":"Es sind 6 Stück mehr. Die 6 zusätzlichen Stück bezogen auf 40 Stück ergeben +15 %. Der Wert liegt unter 20 %.","hint":"Unterscheide die Stückdifferenz vom Prozentwert und nutze 40 Stück als Bezugswert.","steps":"Halte die Angaben aus der Aufgabe getrennt fest. Vergleiche dann jede Auswahl mit diesen Angaben und dem gefragten Kriterium.","example":"Beispiel: Von 20 auf 22 Stück sind es 2 Stück mehr. Bezogen auf 20 Stück entspricht das 10 %.","c":3,"sourceRefs":["M1","M2","M5"],"id":13,"l":2,"type":"multi","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Bike Arena: Veränderung und Ziel","scene":"Die Bike Arena verkaufte 60 Stück in der Vergleichswoche und 75 in der Aktionswoche. Ziel waren mindestens 20 % Zuwachs.","ask":"Welche Angaben stimmen?","options":["Die Stückzahl stieg um 15.","Die Stückzahl stieg um 15 %.","Die Stückzahl stieg um 25 %.","Die Stückzahl stieg um 25 Stück.","Die Bike Arena erfüllte ihr Ziel.","Die Bike Arena erreichte das Ziel genau bei 20 %."],"answer":[0,2,4],"why":"Die Differenz beträgt 15 Stück. 15 ÷ 60 × 100 ergibt +25 %. Das liegt über der Zielmarke.","hint":"Beziehe die zusätzlichen 15 Stück auf den Wert der Vergleichswoche.","steps":"Halte die Angaben aus der Aufgabe getrennt fest. Vergleiche dann jede Auswahl mit diesen Angaben und dem gefragten Kriterium.","example":"Beispiel: Von 20 auf 22 Stück sind es 2 Stück mehr. Bezogen auf 20 Stück entspricht das 10 %.","c":3,"sourceRefs":["M1","M2","M5"],"id":14,"l":2,"type":"multi","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Die gemeinsame Summe einordnen","scene":"Übungsvariante: Jemand addiert die Mengen beider Läden: von 100 auf 121 Stück. Er sagt: „Damit haben beide Läden das Ziel erreicht.“","ask":"Wie bewertest du die Aussage?","options":["Ein gemeinsamer Zuwachs von 21 % bedeutet automatisch mindestens 20 % je Laden.","21 % ist für beide Läden zusammen rechnerisch richtig.","Wenn ein Laden 25 % erreicht, muss man den anderen Standort nicht mehr prüfen.","Da sich beide Läden verbessert haben, sind beide Ziele erfüllt.","Für die Bike Arena gelten die 21 % anstelle des eigenen Prozentwerts.","Das gemeinsame Ergebnis beantwortet die Frage zur Zielerreichung je Laden nicht."],"answer":[1,5],"why":"Die Gesamtsumme wächst um 21 %. Da das Ziel pro Standort gilt, prüft ihr beide einzeln: Block liegt bei +15 %, die Bike Arena bei +25 %.","hint":"Unterscheide, für welche Gruppe der Prozentwert berechnet wurde und für wen die Zielmarke gilt.","steps":"Schreibe kurz auf, was feststeht. Markiere danach Aussagen, die eine Vermutung mit einem Befund verwechseln.","example":"Ein höherer Absatz in einer Aktionswoche zeigt eine Veränderung. Für die Ursache braucht ihr weitere Informationen.","c":1,"sourceRefs":["M1","M2","M5"],"id":15,"l":2,"type":"multi","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Ein Prozentfehler bei der Minipumpe","scene":"Übungsvariante: Die Bike Arena verkaufte P50 zuerst 17-mal und dann 22-mal. Jemand rechnet den Zuwachs mit 5 ÷ 22.","ask":"Welche Korrektur und Aussage sind richtig?","options":["Die fünf zusätzlichen Pumpen sind gleichbedeutend mit +5 %.","Der neue Wert 22 ist die richtige Basis für eine Absatzveränderung.","Der Zuwachs wird als 5 ÷ 17 × 100 gerechnet.","Der Zuwachs beträgt gerundet 29,4 %.","Die Rechnung liefert die Absatzveränderung des gesamten Ladens.","Ein höherer Prozentwert verändert die Stückdifferenz von 5 auf 6."],"answer":[2,3],"why":"Der alte Wert war 17 Stück. 5 ÷ 17 × 100 ergibt gerundet 29,4 % Zuwachs bei der Minipumpe der Bike Arena.","hint":"Welcher Wert beschreibt die Ausgangslage, bevor sich etwas verändert?","steps":"Halte die Angaben aus der Aufgabe getrennt fest. Vergleiche dann jede Auswahl mit diesen Angaben und dem gefragten Kriterium.","example":"Beispiel: Von 20 auf 22 Stück sind es 2 Stück mehr. Bezogen auf 20 Stück entspricht das 10 %.","c":3,"sourceRefs":["M2","M5"],"id":16,"l":2,"type":"multi","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Platzierung bei Block verbessern","scene":"Eine Person entdeckte R40 erst an der Kasse. Eine andere Person wartete im Durchgang, weil am Beratungsplatz ein zweites Rad stand.","ask":"Welche Änderungen reagieren auf diese Beobachtungen?","options":["Den Sattelüberzug allein wegen unveränderter Verkäufe sofort aus dem Sortiment nehmen.","Den Sattelüberzug früher am Zubehörregal sichtbar machen.","Die Anzeige für P50 in der Bike Arena ändern.","Die Vorführung komplett durch ein Aktionsschild am Eingang ersetzen.","Bei der Beratung das zweite Fahrrad außerhalb des Durchgangs abstellen.","Das Kassenregal umstellen, ohne den Standort von R40 zu ändern."],"answer":[1,4],"why":"Die Kundenstimmen geben zwei Hinweise zur Platzierung: R40 früher sichtbar machen und den Durchgang bei der Vorführung freihalten.","hint":"Suche eine Maßnahme pro beobachtetem Problem.","steps":"Lies die Angaben zum Laden. Prüfe für jede Aussage, ob sie durch die Situation oder das genannte Material gedeckt ist.","example":"Eine Rückmeldung zu einer fehlenden Produktangabe kann eine Änderung der Produktkarte begründen.","c":0,"sourceRefs":["M1","M3","M5"],"id":17,"l":2,"type":"multi","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Produktkarten in Leer verbessern","scene":"In der Bike Arena fragt die Kundschaft nach der Rahmengröße für die Tasche und nach den Ventilen, zu denen die Pumpen passen.","ask":"Welche Änderungen machen den Vergleich leichter?","options":["Für die Rahmentasche angeben, zu welchen Rahmengrößen sie passt.","Bei allen Artikeln dieselbe Größenangabe ergänzen.","Nur den Produktnamen „Rahmentasche“ auf der Karte vergrößern.","An der Minipumpe die passenden Ventilarten nennen.","Die Frage zu den Ventilen durch einen Hinweis auf den Preis beantworten.","Das Eingangsschild neu drucken und die Produktkarten unverändert lassen."],"answer":[0,3],"why":"Die Produktkarten sollen die jeweilige Kompatibilität erklären. So beantworten sie die konkreten Fragen zur Tasche und Pumpe.","hint":"Zu welcher Entscheidung brauchen die Kundinnen und Kunden eine konkrete Angabe?","steps":"Lies den Wortlaut genau. Prüfe, ob die Aussage für die betreffende Person oder den betreffenden Laden eindeutig ist.","example":"„75 Stück in der Aktionswoche“ und „plus 15 Stück“ bedeuten Verschiedenes. Eine gute Tabelle beschriftet beide Angaben.","c":4,"sourceRefs":["M1","M3","M5"],"id":18,"l":2,"type":"multi","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Beide Läden einbeziehen","scene":"Block möchte die Beratung verbessern. Die Bike Arena will Zubehör leichter vergleichbar machen.","ask":"Welche Empfehlungen setzen die Wünsche konkret um?","options":["In beiden Läden das Beratungsgespräch durch Selbstbedienung ersetzen.","Für Block einen Beratungsplatz vorsehen, der den Durchgang bei zwei Rädern freihält.","Bei Block alle Produktkarten ersetzen, ohne den Beratungsplatz zu prüfen.","Die Gondeln der Bike Arena in einen betreuten Beratungsstand umwandeln.","Für beide Läden ausschließlich einen gemeinsamen Rabatt vorschlagen.","Die Aktionsgondeln der Bike Arena beibehalten und die Produktkarten für den Vergleich ergänzen."],"answer":[1,5],"why":"Block braucht Platz für Beratung, ohne den Durchgang zu blockieren. Die Bike Arena braucht klare Produktinformationen an ihrer Insel.","hint":"Ordne die Wünsche der Ladenleitungen den passenden nächsten Schritten zu.","steps":"Ordne die Aussagen den Beteiligten zu. Prüfe, welche Rolle und welche Aufgabe jeweils gemeint sind.","example":"Zwei Läden können dieselbe Aktion fortsetzen und trotzdem unterschiedliche Änderungen benötigen.","c":2,"sourceRefs":["M3","M5"],"id":19,"l":2,"type":"multi","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Absatz und Werbewirkung unterscheiden","scene":"Die Bike Arena verkauft 25 % mehr Stück. Eine Person berichtet, dass sie das Eingangsschild neugierig gemacht habe.","ask":"Welche Aussagen sind durch die Informationen gedeckt?","options":["Der Absatz des Aktionssortiments ist um 25 % gestiegen.","Das Eingangsschild verursachte genau 25 % mehr Absatz.","Eine Person berichtet, dass das Schild ihr Interesse geweckt hat.","Die Aussage beweist, dass die Gondeln keine Wirkung hatten.","Mindestens ein Viertel der Kundschaft kam wegen des Schilds.","Der Beitrag des Schilds zum gesamten Zuwachs lässt sich aus diesen Angaben nicht berechnen."],"answer":[0,2,5],"why":"Der Anstieg ist messbar. Die Kundenstimme beschreibt einen einzelnen Besuch. Beides stützt einen weiteren Einsatz des Schilds als Vorschlag. Der Anteil des Schilds am Wachstum bleibt offen.","hint":"Trenne das Ergebnis aus der Rechnung, die einzelne Stimme und eine Behauptung über Ursachen.","steps":"Schreibe kurz auf, was feststeht. Markiere danach Aussagen, die eine Vermutung mit einem Befund verwechseln.","example":"Ein höherer Absatz in einer Aktionswoche zeigt eine Veränderung. Für die Ursache braucht ihr weitere Informationen.","c":1,"sourceRefs":["M2","M3","M5"],"id":20,"l":2,"type":"multi","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Ein Zusatzprodukt abwägen","scene":"Bei Block wurden vor und während der Aktion jeweils fünf Sattelüberzüge R40 verkauft. Eine Person entdeckte ihn erst an der Kasse.","ask":"Welche nächsten Schritte lassen sich mit diesen Angaben begründen?","options":["R40 hat den Absatz von Block um 5 Stück erhöht.","R40 beim nächsten Mal besser sichtbar platzieren und die Stückzahl erneut festhalten.","R40 sofort aus allen Läden entfernen, weil kein Kunde ihn gefunden hat.","Das unveränderte Ergebnis zeigt, dass die Platzierung keinen Einfluss haben kann.","Den R40 in der Fortführung mit einer klaren Prüffrage beibehalten: Wird er an der neuen Stelle früher entdeckt?","R40 muss künftig in die Bike Arena verlegt werden, weil er dort im Bericht bereits mehr verkauft wurde."],"answer":[1,4],"why":"Unveränderter Absatz und spätes Entdecken sprechen dafür, einen sichtbareren Platz zu testen. Danach lässt sich der Absatz für R40 gezielt prüfen.","hint":"Ein unveränderter Absatz nennt noch keine Ursache. Nutze die Kundenrückmeldung als Hinweis für einen Test.","steps":"Lies die Angaben zum Laden. Prüfe für jede Aussage, ob sie durch die Situation oder das genannte Material gedeckt ist.","example":"Eine Rückmeldung zu einer fehlenden Produktangabe kann eine Änderung der Produktkarte begründen.","c":0,"sourceRefs":["M2","M3","M5"],"id":21,"l":2,"type":"multi","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Die Ergebnisse kurz berichten","scene":"Übungsvariante: Jan hat wenig Zeit. Du möchtest genau sagen, welcher Laden sein Ziel erreicht hat und was sich ändern soll.","ask":"Welche Aussagen passen in eine verlässliche Kurzvorlage?","options":["„Block: 40 → 46 Stück, +15 %, Ziel verfehlt.“","„Bike Arena: 60 → 75 Stück, +15 %, Ziel erreicht.“","„Beide Läden zusammen: +21 %. Beide erreichen damit jeweils ihr Ziel.“","„Bike Arena: Ergänzt die Rahmengröße auf der Taschenkarte. Diese Angabe fehlte beim Vergleich.“","„Block: Wählt eine neue Werbemaßnahme, weil sich keine Person an den Newsletter erinnern konnte.“","„Bike Arena: Die ursprüngliche Werbemaßnahme muss weg, weil Block sein Ziel verfehlte.“"],"answer":[0,3],"why":"Die Kurzvorlage soll die richtigen Standortwerte nennen und eine konkret belegte Änderung vorschlagen.","hint":"Prüfe erst die Zuordnung der Zahlen und danach den Zusammenhang zwischen Änderung und Rückmeldung.","steps":"Lies den Wortlaut genau. Prüfe, ob die Aussage für die betreffende Person oder den betreffenden Laden eindeutig ist.","example":"„75 Stück in der Aktionswoche“ und „plus 15 Stück“ bedeuten Verschiedenes. Eine gute Tabelle beschriftet beide Angaben.","c":4,"sourceRefs":["M2","M3","M5"],"id":22,"l":2,"type":"multi","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Die Idee an einem neuen Standort prüfen","scene":"Jan überlegt, ob die Aktion auch zu einem weiteren Fahrradladen in Aurich mit Werkstatt passen könnte.","ask":"Welche Informationen braucht ihr für eine Empfehlung an diesen Laden?","options":["Die durchschnittliche Zielerreichung der beiden bisherigen Standorte als einzige Entscheidungsgrundlage","Welche Zubehörartikel die Kundschaft des neuen Ladens häufig nachfragt","Wo Zubehör und ein Rad zum Ausprobieren Platz finden","Ob der dritte Laden voraussichtlich dieselben Stückzahlen verkauft, weil er in Aurich liegt","Ob das Team Zeit für eine Vorführung oder Beratung einplanen kann","Welche Farben das Eingangsschild der Bike Arena hatte, damit sie unverändert übernommen werden"],"answer":[1,2,4],"why":"Nachfrage, verfügbare Fläche und Möglichkeiten für Beratung helfen bei der Standortentscheidung. Ergebnisse von Block und der Bike Arena lassen sich nicht ohne Prüfung übertragen.","hint":"Überlege, welche Unterschiede bei Angebot, Platz und Beratung die Umsetzung ändern können.","steps":"Ordne die Aussagen den Beteiligten zu. Prüfe, welche Rolle und welche Aufgabe jeweils gemeint sind.","example":"Zwei Läden können dieselbe Aktion fortsetzen und trotzdem unterschiedliche Änderungen benötigen.","c":2,"sourceRefs":["Handlungssituation"],"id":23,"l":2,"type":"multi","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Den Bericht eröffnen","scene":"Beide Läden wollen bis Freitag wissen, ob und wie die Frühjahrsaktion weitergeht. Jan braucht eine Empfehlung je Standort.","ask":"Mit welchem Schwerpunkt beginnst du die Vorbereitung?","options":["Prüfe zuerst die Standortwerte und die Rechnung zur Zielerreichung.","Sammle zuerst die wichtigsten Wünsche der beiden Läden und Fragen der Kundschaft.","Kläre zuerst, wer bis Freitag entscheidet und wer Änderungen vor Ort umsetzen kann.","Stelle Stückzahlen und Kundenstimmen pro Standort nebeneinander und markiere, was sie jeweils belegen.","Bereite eine kurze Abstimmung mit den Läden vor, damit du ihre Wünsche für die Folgeaktion richtig einordnen kannst.","Plane einen kurzen Ablauf für Datenauswertung, Freigabe und Rückmeldung bis Freitag."],"consequences":["Deine Empfehlung beginnt mit dem Absatz und dem Zielwert.","Deine Empfehlung beginnt mit Erwartungen und Rückmeldungen.","Deine Empfehlung beginnt mit Zuständigkeiten und der Umsetzungsfrist.","Du legst zwei Arten von Belegen für die Standortentscheidung bereit.","Du bindest beide Standorte in die Vorbereitung der Entscheidung ein.","Deine Entscheidungsvorlage hat einen realistischen Zeit- und Arbeitsrahmen."],"why":"Deine Entscheidungen werden als Kette ausgewertet. Prüfe bei jedem Schritt, wie er deine bisherige Begründung weiterführt.","hint":"Wähle deinen Schwerpunkt für den gesamten Entscheidungsweg.","steps":"Ruf deine bisherige Entscheidung auf. Prüfe die neue Lage. Wähle einen Schritt, der zu deinem Arbeitsweg passt.","example":"Eine Rückmeldung zu einer fehlenden Produktangabe kann eine Änderung der Produktkarte begründen.","c":0,"sourceRefs":["Handlungssituation","M1","M5"],"id":24,"l":3,"type":"story","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","storyIndex":0,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen."},{"title":"Blocks Ergebnis einordnen","scene":"Block steigt von 40 auf 46 Stück und verfehlt mit +15 % das Ziel von +20 %. Die Ladenleitung möchte weitermachen, wenn sich etwas ändert.","ask":"Wie bereitest du Blocks Entscheidung vor?","options":["Stelle Zuwachs und Zielabstand gegenüber und suche zu jeder vorgeschlagenen Änderung einen Beleg.","Kläre mit Blocks Ladenleitung, welche praktische Änderung eine erneute Teilnahme erleichtert.","Kläre, welchen Umbau Block vor dem nächsten Termin leisten kann und wer am Samstag die Beratung übernimmt.","Ordne die gleich gebliebenen Verkäufe von R40 und den Hinweis zum späten Entdecken als Prüfansatz für die Platzierung ein.","Vergleiche den Wunsch der Ladenleitung mit der Rückmeldung zum Warten im Durchgang.","Sichere den Termin vorläufig und halte fest, dass Block erst nach Klärung der Änderung verbindlich zusagt."],"consequences":["Du zeigst sowohl den Aufwärtstrend als auch die Zielverfehlung.","Die Folgeaktion kann an einer konkreten Anforderung des Ladens ansetzen.","Du prüfst, welche Anpassung vor Ort tatsächlich machbar ist.","Du verknüpfst zwei Hinweise, ohne daraus bereits eine Ursache abzuleiten.","Ein konkreter Kundenhinweis ergänzt die Sicht des Betriebs.","Du bewahrst den Zeitrahmen und respektierst Blocks Bedingung."],"why":"Deine Entscheidungen werden als Kette ausgewertet. Prüfe bei jedem Schritt, wie er deine bisherige Begründung weiterführt.","hint":"Nutze Blocks Wunsch und die Zielabweichung passend zu deinem Arbeitsweg.","steps":"Ruf deine bisherige Entscheidung auf. Prüfe die neue Lage. Wähle einen Schritt, der zu deinem Arbeitsweg passt.","example":"Beispiel: Von 20 auf 22 Stück sind es 2 Stück mehr. Bezogen auf 20 Stück entspricht das 10 %.","c":3,"sourceRefs":["Handlungssituation","M2","M3","M5"],"id":25,"l":3,"type":"story","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","storyIndex":1,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":24,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"title":"Die Bike Arena auswerten","scene":"Die Bike Arena erreicht +25 %. Einige Stimmen loben die schnelle Suche oder das Schild. Zur Rahmentasche und zur Minipumpe fehlen Angaben für den Produktvergleich.","ask":"Wie gehst du mit dem guten Ergebnis und den Rückfragen um?","options":["Dokumentiere das erreichte Ziel und nenne getrennt den Beleg für bessere Produktkarten.","Lass den Laden priorisieren, welche Kundenfrage auf den Karten zuerst beantwortet werden soll.","Plane ein, wer Rahmengrößen und Ventilangaben bis zur nächsten Aktion prüft und einträgt.","Belege aus den Stückzahlen den Erfolg der Aktion und nutze die Kundenstimmen für je eine Ergänzung an Tasche und Pumpe.","Bitte das Team, seine häufigsten Fragen an der Gondel mit den beiden vorhandenen Kundenhinweisen abzugleichen.","Diskutiere eine kleine Änderung der Produktkarten, die der Laden vor dem gewünschten Termin umsetzen kann."],"consequences":["Du unterscheidest den Absatzbefund vom Grund für die konkrete Änderung.","Die Produktkarten greifen die Kundensicht und die Erfahrungen der Mitarbeitenden auf.","Die Verbesserung erhält eine prüfbare Aufgabe mit Zuständigkeit.","Du leitest Zielurteil und Produktangaben aus passenden Belegen ab.","Du beziehst zusätzliche Erfahrungen der Personen ein, die die Gondel betreuen.","Die gute Platzierung kann bleiben, während die Produktinformationen innerhalb der verfügbaren Zeit ergänzt werden."],"why":"Deine Entscheidungen werden als Kette ausgewertet. Prüfe bei jedem Schritt, wie er deine bisherige Begründung weiterführt.","hint":"Behalte das erreichte Ziel im Blick und prüfe die offenen Produktinformationen.","steps":"Ruf deine bisherige Entscheidung auf. Prüfe die neue Lage. Wähle einen Schritt, der zu deinem Arbeitsweg passt.","example":"„75 Stück in der Aktionswoche“ und „plus 15 Stück“ bedeuten Verschiedenes. Eine gute Tabelle beschriftet beide Angaben.","c":4,"sourceRefs":["M2","M3","M5"],"id":26,"l":3,"type":"story","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","storyIndex":2,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":25,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"title":"Werbung für beide Läden abstimmen","scene":"Block möchte den Newsletter behalten. Eine Person berichtet, dass das Eingangsschild der Bike Arena sie neugierig gemacht habe.","ask":"Wie formulierst du den Werbeteil der Empfehlung?","options":["Empfiehl beide vorhandenen Mittel mit je einem Beleg und markiere, was über ihre Werbewirkung offenbleibt.","Gib beiden Ladenleitungen ihre jeweiligen Kundenhinweise zurück und hole eine Rückmeldung zum geplanten Werbemittel ein.","Kläre für beide Mittel, wer die Texte aktualisiert und wann Newsletter und Schild vorliegen müssen.","Nenne den Newsletterhinweis zur Vorführung bei Block und den berichteten ersten Eindruck am Eingang in Leer als zwei getrennte Belege.","Bitte beide Läden, beim nächsten Termin einige Kundinnen und Kunden zu fragen, wie sie auf die Aktion aufmerksam wurden.","Übernimm die unterschiedlichen Werbemittel in den Ablaufplan und ordne pro Laden eine verantwortliche Person zu."],"consequences":["Du begründest die getrennten Empfehlungen, ohne eine sichere Ursache zu behaupten.","Du nutzt Kundenstimmen als Gesprächsgrundlage mit den Läden.","Du hältst die Umsetzung für beide Werbemittel im vereinbarten Zeitrahmen.","Die Empfehlung bleibt für jeden Laden einzeln nachvollziehbar.","Du planst eine Rückmeldung, die für die nächste Entscheidung mehr Sichtweisen liefert.","Du sicherst, dass beide Werbemittel rechtzeitig bereitstehen."],"why":"Deine Entscheidungen werden als Kette ausgewertet. Prüfe bei jedem Schritt, wie er deine bisherige Begründung weiterführt.","hint":"Wähle einen nächsten Schritt, der aus den unterschiedlichen Rückmeldungen folgt.","steps":"Ruf deine bisherige Entscheidung auf. Prüfe die neue Lage. Wähle einen Schritt, der zu deinem Arbeitsweg passt.","example":"Zwei Läden können dieselbe Aktion fortsetzen und trotzdem unterschiedliche Änderungen benötigen.","c":2,"sourceRefs":["M1","M3","M5"],"id":27,"l":3,"type":"story","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","storyIndex":3,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":26,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"title":"Die Grenzen der Auswertung benennen","scene":"Übungsvariante: Im Vorbereitungsgespräch meint jemand: „Die Prozentzahlen reichen doch. Damit wissen wir, ob Newsletter oder Schild besser funktionieren.“","ask":"Wie hältst du deine Empfehlung fachlich sauber?","options":["Stelle klar: Die Zahlen zeigen Absatzveränderungen. Für einen Vergleich der Werbewirkung fehlt ein Nachweis.","Ergänze die Prozentzahlen durch einzelne Kundenstimmen und kennzeichne, von wem die Aussagen tatsächlich kommen.","Vereinbare für die Folgeaktion einen Zeitpunkt und eine Zuständigkeit, um die Wirkung der Werbung gezielter zu prüfen.","Erläutere, dass Angebot, Platzierung und Werbung im selben Zeitraum zusammenwirken können. Beziehe die Rechnung allein auf die Absatzmenge.","Besprich mit den Ladenleitungen, welche Kundenfragen sie beim nächsten Termin aufnehmen möchten.","Kennzeichne die Werbeempfehlung in der Kurzvorlage als vorläufig. Plane eine kurze Überprüfung während der Folgeaktion ein."],"consequences":["Du trennst, was sich berechnen lässt und was die Daten nicht klären.","Du nutzt die dokumentierten Sichtweisen in ihrem tatsächlichen Umfang.","Du machst aus der offenen Frage einen planbaren Prüfschritt.","Du begrenzt die Schlussfolgerung auf das, was der Vergleich zeigt.","Du beziehst die Betriebe in die Klärung der offenen Werbefrage ein.","Du schlägst eine umsetzbare Entscheidung vor und lässt Raum für neue Erkenntnisse."],"why":"Deine Entscheidungen werden als Kette ausgewertet. Prüfe bei jedem Schritt, wie er deine bisherige Begründung weiterführt.","hint":"Behalte deinen Schwerpunkt und erkläre die Grenze der vorhandenen Zahlen.","steps":"Ruf deine bisherige Entscheidung auf. Prüfe die neue Lage. Wähle einen Schritt, der zu deinem Arbeitsweg passt.","example":"Ein höherer Absatz in einer Aktionswoche zeigt eine Veränderung. Für die Ursache braucht ihr weitere Informationen.","c":1,"sourceRefs":["M1","M2","M3","M5"],"id":28,"l":3,"type":"story","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","storyIndex":4,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":27,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"title":"Die Entscheidung an Jan weitergeben","scene":"Übungsvariante: Jan bittet am Freitag um eine letzte Empfehlung. Beide Läden hätten Platz, wenn die abgestimmten Änderungen bis zum nächsten Termin vorbereitet werden.","ask":"Welche Schlussfassung passt zu dem begonnenen Arbeitsweg?","options":["Empfiehl Block eine überarbeitete Fortführung und der Bike Arena eine Fortführung mit besseren Karten. Nenne +15 % und +25 % als Standortbelege.","Empfiehl eine Fortführung mit der Aufnahme von Blocks Beratungswunsch und den Vergleichsfragen aus Leer. Vereinbare eine gemeinsame Rückmeldung nach der Aktion.","Empfiehl die Termine unter der Bedingung, dass Block den Beratungsplatz und Leer seine Produktkarten rechtzeitig vorbereitet. Halte die Zuständigkeiten fest.","Halte die Zielerreichung je Laden fest und verknüpfe die Empfehlungen zu Angebot, Fläche und Werbung mit konkreten Belegen aus der Auswertung.","Gib beiden Ladenleitungen ihre Wünsche und die passenden Vorschläge zur letzten Abstimmung zurück. Notiere noch offene Rückfragen für Jan.","Lege einen Ablauf mit Bestätigung bis Freitag, Änderungen vor dem Termin und Auswertung danach vor."],"consequences":["Jan kann die Empfehlungen mit den berechneten Ergebnissen und den Änderungen verbinden.","Die Empfehlung verbindet beide Perspektiven mit einem vereinbarten Rückmeldeschritt.","Die Entscheidung ist an klare Voraussetzungen für die Umsetzung gebunden.","Der Entscheidungsweg bleibt für Jan und beide Läden überprüfbar.","Die Empfehlung bleibt an die Bedürfnisse der Läden und ihrer Kundschaft rückgebunden.","Du führst die Entscheidung bis zur Durchführung und erneuten Prüfung weiter."],"why":"Deine Entscheidungen werden als Kette ausgewertet. Prüfe bei jedem Schritt, wie er deine bisherige Begründung weiterführt.","hint":"Schließe mit einer klaren Empfehlung und dem nächsten Schritt für jeden Laden ab.","steps":"Ruf deine bisherige Entscheidung auf. Prüfe die neue Lage. Wähle einen Schritt, der zu deinem Arbeitsweg passt.","example":"Eine Rückmeldung zu einer fehlenden Produktangabe kann eine Änderung der Produktkarte begründen.","c":0,"sourceRefs":["Handlungssituation","M2","M3","M5"],"id":29,"l":3,"type":"story","caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","storyIndex":5,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":28,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"title":"Termin aus den Nachrichten","scene":"Zwei Geschäfte haben Global Bike nach der Aktion um Rückmeldung gebeten.","ask":"Welche Notiz hält den gemeinsamen Termin richtig fest?","options":["Bis Montag brauchen beide eine Antwort","Bis Freitag braucht nur Block eine Antwort","Bis Freitag brauchen beide eine Antwort","Bis Freitag muss die nächste Aktion starten","Bis Freitag entscheidet allein die Bike Arena","Beide haben bereits verbindlich zugesagt"],"answer":[2],"why":"Freitag ist die Frist für Global Bikes Antwort an beide. Ein Starttermin steht noch nicht fest.","hint":"Suche nach der Frist für die Antwort.","steps":"Lies zuerst, wer auf die Antwort wartet. Ordne danach jedem Geschäft sein Anliegen zu.","example":"Ein Geschäft möchte einen Termin. Ein anderes möchte vor der Zusage etwas klären.","id":30,"coreId":0,"reserveNo":1,"type":"multi","l":1,"c":2,"caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["Handlungssituation"]},{"title":"Wünsche in die Übergabe schreiben","scene":"Übungsvariante: Du übergibst die Nachrichten der Läden an eine Kollegin, die den Fall noch nicht kennt.","ask":"Was muss in der Übergabe stehen?","options":["Die Bike Arena verlangt dieselben Änderungen wie Block","Die Garage der Bike Arena muss bis Freitag frei sein","In Leer soll der nächste Termin besprochen werden","Jan kann mit der Antwort warten, bis beide Läden selbst entscheiden","Block hat die Teilnahme schon bestätigt","In Aurich kommt eine Wiederholung mit Änderungen infrage"],"answer":[2,5],"why":"Block will Bedingungen klären. Die Bike Arena möchte einen Termin absprechen. Beide erwarten bis Freitag eine Antwort.","hint":"Lies die beiden Nachrichten getrennt und halte die Anliegen pro Standort fest.","steps":"Lies zuerst, wer auf die Antwort wartet. Ordne danach jedem Geschäft sein Anliegen zu.","example":"Ein Geschäft möchte einen Termin. Ein anderes möchte vor der Zusage etwas klären.","id":31,"coreId":0,"reserveNo":2,"type":"multi","l":1,"c":2,"caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["Handlungssituation"]},{"title":"Prozentwert und Einheit","scene":"Christian nennt den Maßstab aus dem Aktionsbericht.","ask":"Welche Angabe gehört in sein Prüffeld?","options":["Mindestens 20 % mehr Werbung am Eingang","Mindestens 20 neue Kundinnen und Kunden","Genau 20 Stück Mehrabsatz in beiden Läden zusammen","Mehr als 20 € Umsatz zusätzlich je Öffnungstag","20 Artikel im Sortiment","Mindestens 20 % Zuwachs bei den verkauften Stücken"],"answer":[5],"why":"Christian meint Stückzahlen im Vergleich zur Vergleichswoche des jeweiligen Ladens. Der Zielwert ist eine Untergrenze.","hint":"Welches Ergebnis wird als Stückzahl erfasst?","steps":"Markiere Messgröße, Zeitraum und Zielwert. Vergleiche erst dann das Ergebnis.","example":"„Mindestens 10 %“ ist auch bei genau 10 % erfüllt.","id":32,"coreId":1,"reserveNo":1,"type":"multi","l":1,"c":0,"caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["Handlungssituation","M1"]},{"title":"Ziel an der Untergrenze","scene":"Übungsvariante: Ein Laden verkauft 50 Stück in der Vergleichswoche und 60 Stück in der Aktion.","ask":"Wie entscheidest du nach Christians Zielregel?","options":["Der Zuwachs beträgt 10 von 50 Stück und damit 20 %","Der Laden verfehlt das Ziel, weil er 20 Stück mehr verkaufen müsste","Der Laden erreicht das Ziel genau","Das Ziel ist erst bei 61 Stück erreicht","Der Prozentwert wird mit dem anderen Laden verglichen","20 % beziehen sich auf den Umsatz der Aktion"],"answer":[0,2],"why":"Der Zuwachs liegt genau bei der Mindestanforderung. Der alte Absatz ist der Bezugswert.","hint":"Was schließt das Wort „mindestens“ ein?","steps":"Markiere Messgröße, Zeitraum und Zielwert. Vergleiche erst dann das Ergebnis.","example":"„Mindestens 10 %“ ist auch bei genau 10 % erfüllt.","id":33,"coreId":1,"reserveNo":2,"type":"multi","l":1,"c":0,"caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["Handlungssituation","M1"]},{"title":"Schlösser bei Block","scene":"M2 nennt Block und die Vergleichswoche. Für das Bügelschloss S20 steht in der Zelle eine 10.","ask":"Wie liest du die Zelle korrekt?","options":["10 Schlösser lagen im Lager","Das Schloss kostete im Vergleich 10 €","10 Personen fragten nach einem Schloss","10 Schlösser wurden im Vergleichszeitraum verkauft","10 Schlösser wurden zusätzlich verkauft","Die Aktion brachte 10 € mehr Umsatz"],"answer":[3],"why":"Die Tabelle gibt verkaufte Stücke je Artikel, Laden und Woche an.","hint":"Beginne mit Artikel und Spaltenkopf, danach lies die Zahl.","steps":"Lies den Artikel und den Spaltenkopf. Prüfe dann die Einheit und Bedeutung der Zahl.","example":"„12 Stück“ beschreibt eine Menge. „12 €“ wäre ein Geldbetrag.","id":34,"coreId":2,"reserveNo":1,"type":"multi","l":1,"c":0,"caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M6"]},{"title":"Menge und Änderung im Bericht","scene":"In der Bike Arena stieg der Absatz des LED-Lichtsets L10 von 10 auf 13 Stück.","ask":"Welche Angaben kannst du aus dem Ausschnitt belegen?","options":["3 Lichtsets mehr wurden gegenüber der Vergleichswoche verkauft","3 € nahm der Laden pro Lichtset mehr ein","Die Zahl 13 steht für alle zusätzlich verkauften Lichtsets","Es kamen genau 13 Personen, um ein Lichtset zu kaufen","13 € waren der Umsatz in der Aktionswoche","13 Lichtsets wurden während der Aktion verkauft"],"answer":[0,5],"why":"Die 13 ist der Aktionsabsatz. Die Differenz zur Vergleichswoche beträgt 3 Stück. Angaben zu Preisen oder Personen fehlen.","hint":"Trenne die Zahl einer einzelnen Woche von der Differenz zwischen beiden Wochen.","steps":"Lies den Artikel und den Spaltenkopf. Prüfe dann die Einheit und Bedeutung der Zahl.","example":"„12 Stück“ beschreibt eine Menge. „12 €“ wäre ein Geldbetrag.","id":35,"coreId":2,"reserveNo":2,"type":"multi","l":1,"c":0,"caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M6"]},{"title":"Die beiden passenden Spalten","scene":"Du willst den Absatz von Block vor und während der Aktion vergleichen.","ask":"Welche Spalten legst du nebeneinander?","options":["Block Vergleichswoche und Bike Arena Aktionswoche","Bike Arena Vergleichswoche und Bike Arena Aktionswoche","Die erste und letzte Spalte ohne Rücksicht auf den Standort","Block Vergleichswoche und Bike Arena Vergleichswoche","Bike Arena Aktionswoche und Block Aktionswoche","Block Vergleichswoche und Block Aktionswoche"],"answer":[5],"why":"Die Auswertung vergleicht einen Standort mit seinem eigenen Ausgangswert.","hint":"Prüfe zuerst den Ladennamen auf beiden Spalten.","steps":"Ordne die Spalten nach Laden und Woche. Prüfe, ob für sie dieselben Bedingungen gelten.","example":"Beim Standortvergleich hat jede Zeile zwei Wochen desselben Ladens.","id":36,"coreId":3,"reserveNo":1,"type":"multi","l":1,"c":3,"caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M2","M5"]},{"title":"Leeres Feld und Öffnungstage","scene":"Übungsvariante: Jemand hält die Lücke beim Sattelüberzug in Leer für einen Lieferengpass. Eine andere Person prüft die Öffnungstage.","ask":"Welche Aussagen klären beides?","options":["Jeder Laden war in jeder der beiden Wochen fünf Tage geöffnet","Der Sattelüberzug war in Leer in beiden Wochen ausverkauft","Der Leerer Absatz ist für den Vergleich immer um einen Tag zu kürzen","Der Sattelüberzug gehört in Leer nicht zur Aktion","Das leere Feld ist die Zahl der Beschwerden zum Sattelüberzug","In Aurich betrifft der Sattelüberzug nur die Vergleichswoche"],"answer":[0,3],"why":"M2 erklärt leere Felder mit der Auswahl der Aktionsartikel. M1 nennt fünf gleiche Öffnungstage je Woche und Standort.","hint":"Suche die Erklärung zur leeren Zelle in M2 und den Zeitrahmen in M1.","steps":"Ordne die Spalten nach Laden und Woche. Prüfe, ob für sie dieselben Bedingungen gelten.","example":"Beim Standortvergleich hat jede Zeile zwei Wochen desselben Ladens.","id":37,"coreId":3,"reserveNo":2,"type":"multi","l":1,"c":3,"caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M2","M5"]},{"title":"Die Ausgangszahl finden","scene":"Übungsvariante: Vor der Aktion verkauft ein Laden 30 Stück, während der Aktion 36.","ask":"Durch welche Zahl teilst du die Zunahme von 6 Stück?","options":["Durch 30","Durch 36","Durch 6","Durch 66","Durch 20","Durch 100"],"answer":[0],"why":"Die ursprünglichen 30 Stück sind die Bezugsgröße der Veränderung.","hint":"Welche Menge stand fest, bevor die Aktion begann?","steps":"Ziehe die alte Menge von der neuen Menge ab. Verwende die alte Menge als Nenner.","example":"Ein Plus von 10 Stück bei vorher 100 Stück ergibt +10 %.","id":38,"coreId":4,"reserveNo":1,"type":"multi","l":1,"c":3,"caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M5","M6"]},{"title":"Einen Rückgang berechnen","scene":"Übungsvariante: Ein Laden sinkt von 50 auf 45 Stück. Er will die Veränderung in Prozent ausweisen.","ask":"Welche Rechenschritte stimmen?","options":["45 minus 50 ergibt −5 Stück","Die 45 Stück durch 50 teilen und mit dem Ergebnis +90 % Zuwachs melden","−5 durch 50 teilen und mit 100 multiplizieren, also −10 %","5 durch 45 teilen, weil das die neuere Menge ist","5 durch 45 teilen und den Rückgang als −11,1 % angeben","50 von 45 abziehen und +5 Stück eintragen"],"answer":[0,2],"why":"Der alte Wert bleibt auch bei einem Rückgang die Basis. Die negative Differenz zeigt die Richtung an.","hint":"Bestimme zuerst die Richtung der Veränderung, dann den Bezugswert.","steps":"Ziehe die alte Menge von der neuen Menge ab. Verwende die alte Menge als Nenner.","example":"Ein Plus von 10 Stück bei vorher 100 Stück ergibt +10 %.","id":39,"coreId":4,"reserveNo":2,"type":"multi","l":1,"c":3,"caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M5","M6"]},{"title":"Bügelschloss in beiden Läden","scene":"Du sollst aus M1 einen gemeinsamen Aktionsartikel für beide Läden nennen.","ask":"Welche Warenzeile steht tatsächlich in beiden Sortimenten?","options":["Bügelschloss S20","F60 und B80","R40 und B80","Flaschenhalter F60","Reflektorband B80","Sattelüberzug R40"],"answer":[0],"why":"Das Bügelschloss S20 ist Bestandteil des gemeinsamen Angebots. F60 und B80 gehören nur in Leer dazu, R40 nur in Aurich.","hint":"Suche denselben Artikelcode in beiden Kernsortimenten.","steps":"Vergleiche die Listen je Laden. Markiere zuerst die gemeinsam geführten Artikel.","example":"Ein Produkt im Angebot beider Läden kann zum gemeinsamen Sortiment gehören.","id":40,"coreId":5,"reserveNo":1,"type":"multi","l":1,"c":0,"caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1"]},{"title":"Eine gemeinsame Produktliste erstellen","scene":"Übungsvariante: Global Bike legt einen gemeinsamen Bestellzettel und je einen lokalen Zusatzauftrag an.","ask":"Welche Artikel kommen auf den gemeinsamen Bestellzettel?","options":["Minipumpe P50","Reflektorband B80","Rahmentasche T30","Flaschenhalter F60","LED-Lichtset L10","Sattelüberzug R40"],"answer":[0,2,4],"why":"T30, L10 und P50 finden sich zusammen mit S20 in beiden Läden. Die übrigen genannten Artikel sind lokale Ergänzungen.","hint":"Übernimm Artikel nur, wenn sie für beide Standorte gemeinsam vorgesehen sind.","steps":"Vergleiche die Listen je Laden. Markiere zuerst die gemeinsam geführten Artikel.","example":"Ein Produkt im Angebot beider Läden kann zum gemeinsamen Sortiment gehören.","id":41,"coreId":5,"reserveNo":2,"type":"multi","l":1,"c":0,"caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1"]},{"title":"Werbung am Eingang","scene":"Im Aktionsbericht steht je ein eigenes Werbemittel für Block und die Bike Arena.","ask":"Welche Zuordnung kannst du als Beschriftung übernehmen?","options":["Bike Arena: Schild am Eingang","Block: Schild am Eingang für die nächste Tour","Bike Arena: Einladungsnewsletter zur Beratung","Block: Produktkarten an zwei Gondeln","Bike Arena: Vorführung am Beratungsplatz im Newsletter","Beide: derselbe Newsletter am Montag"],"answer":[0],"why":"In Leer wirbt das Schild am Eingang. In Aurich lädt der Newsletter zur Beratung ein.","hint":"Lies in M1 die Zeile mit dem Werbemittel am jeweiligen Standort.","steps":"Markiere je Angabe den Standort. Unterscheide dann Werbemittel und Platzierung.","example":"Ein Plakat weist auf Ware hin. Ein Warenträger zeigt, wo sie angeboten wird.","id":42,"coreId":6,"reserveNo":1,"type":"multi","l":1,"c":4,"caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1"]},{"title":"Spalten in einer Präsentation","scene":"Übungsvariante: Auf einer Folie wurden „Werbung“ und „Platzierung“ vertauscht. Du sortierst die Angaben neu.","ask":"Welche Zeilen gehören unter die jeweils angegebene Überschrift?","options":["Platzierung in Leer: Schild mit Gruß zur nächsten Tour","Werbung in Leer: Schild am Eingang","Platzierung bei Block: Newsletterversand am Montag","Werbung in Leer: Lichtvorführung am Rad im Newsletter","Platzierung bei Block: Zubehör an Warenträgern mit Vorführung am Beratungsplatz","Werbung bei Block: zwei Gondeln mit Karten zur Selbstbedienung"],"answer":[1,4],"why":"Bei der Platzierung geht es um Warenstandorte oder Vorführung. Ein Eingangsschild spricht die Kundschaft an und zählt hier als Werbemittel.","hint":"Prüfe bei jeder Zeile zuerst den Laden und dann die Überschrift.","steps":"Markiere je Angabe den Standort. Unterscheide dann Werbemittel und Platzierung.","example":"Ein Plakat weist auf Ware hin. Ein Warenträger zeigt, wo sie angeboten wird.","id":43,"coreId":6,"reserveNo":2,"type":"multi","l":1,"c":4,"caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1"]},{"title":"Die passende Empfehlungskarte","scene":"Ein Team möchte den Newsletter beim nächsten Termin zwei Tage früher senden.","ask":"Unter welche Überschrift kommt diese Empfehlung?","options":["Vergleichsabsatz","Produktbestand","Zielerreichung","Sortiment","Platzierung","Werbung"],"answer":[5],"why":"Der Newsletter ist ein Werbemittel. Ein anderer Versandtag verändert, wann die Kundschaft angesprochen wird.","hint":"Überlege, ob sich Ware, Standort der Ware oder Ansprache ändert.","steps":"Nenne die Veränderung in einem kurzen Satz. Prüfe, ob sie Ware, Platz oder Ansprache betrifft.","example":"Eine neue Ware verändert das Sortiment. Ein neuer Standort derselben Ware verändert die Platzierung.","id":44,"coreId":7,"reserveNo":1,"type":"multi","l":1,"c":0,"caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["Handlungssituation","M4","M5"]},{"title":"Drei Änderungen einordnen","scene":"Übungsvariante: Für die Folgeaktion schlägt das Team drei Dinge vor: ein zweites Minipumpenmodell anbieten, B80 neben den Eingang legen und den Newsletter mit einem neuen Betreff verschicken.","ask":"Welche Zuordnungen stimmen?","options":["Werbung: einen neuen Newsletter-Betreff verwenden","Werbung: ein zweites Minipumpenmodell anbieten","Sortiment: ein zweites Minipumpenmodell anbieten","Platzierung: B80 neben den Eingang legen","Sortiment: B80 innerhalb des Ladens verlegen","Platzierung: einen neuen Newsletter-Betreff eintragen"],"answer":[0,2,3],"why":"Mit einem zweiten Minipumpenmodell ändert sich die Auswahl. Das Verschieben des Reflektorbands ändert den Warenstandort. Ein neuer Betreff verändert die Ansprache.","hint":"Ordne jede Maßnahme genau einer Frage zu: Was, wo oder wie davon erfahren?","steps":"Nenne die Veränderung in einem kurzen Satz. Prüfe, ob sie Ware, Platz oder Ansprache betrifft.","example":"Eine neue Ware verändert das Sortiment. Ein neuer Standort derselben Ware verändert die Platzierung.","id":45,"coreId":7,"reserveNo":2,"type":"multi","l":1,"c":0,"caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["Handlungssituation","M4","M5"]},{"title":"Eine Kundenmeinung richtig wiedergeben","scene":"Eine Person bei Block fand das Bügelschloss griffbereit und konnte es am Rahmen ausprobieren.","ask":"Welche Aussage kannst du sicher in einen Bericht übernehmen?","options":["Alle Kundinnen und Kunden fanden den Platz günstig","Die Aktion muss allein wegen des Schlosses wiederholt werden","Das Schloss hat wegen seiner Platzierung mehr Absatz erzielt","Diese Person fand das Schloss griffbereit und probierte es am Rahmen aus","Die Beratung erzeugte genauso viele zusätzliche Verkäufe wie das Schloss","Die Mehrheit der Kundschaft durfte das Schloss ausprobieren"],"answer":[3],"why":"M3 dokumentiert die Erfahrung einer Person. Aussagen über die Mehrheit oder die Wirkung auf den Absatz sind damit offen.","hint":"Bleibe bei der Person, die die Rückmeldung gegeben hat.","steps":"Schreibe auf, was die Person tatsächlich gesagt hat. Prüfe jede Folgerung an diesem Satz.","example":"Wenn eine Person eine Kiste rasch findet, ist damit nicht die Erfahrung aller beschrieben.","id":46,"coreId":8,"reserveNo":1,"type":"multi","l":1,"c":1,"caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M3"]},{"title":"Eine Kundenstimme als Beleg nutzen","scene":"Übungsvariante: Ein Teammitglied meint: „Eine Person fand ihre Pumpe schnell, also wird die gesamte Kundschaft sie jedes Mal finden.“","ask":"Welche Antworten ordnen den Beleg korrekt ein?","options":["Damit lassen sich besondere Fragen zu den Ventilen ausschließen","Das Lob ist wertlos, weil keine Umsatzsumme genannt wurde","Beim nächsten Termin könnt ihr weitere Rückmeldungen zur Auffindbarkeit sammeln","Die Aussage sagt direkt, wie viele Personen die richtige Gondel fanden","Der Satz beweist, dass die Gondel den gesamten Zuwachs auslöst","Die Äußerung spricht dafür, dass die Pumpe in diesem Fall gut zu finden war"],"answer":[2,5],"why":"Eine einzelne positive Stimme ist ein Hinweis. Weitere Rückmeldungen helfen einzuschätzen, wie verbreitet die Erfahrung war.","hint":"Welche Aussage lässt sich dieser einen Erfahrung direkt entnehmen?","steps":"Schreibe auf, was die Person tatsächlich gesagt hat. Prüfe jede Folgerung an diesem Satz.","example":"Wenn eine Person eine Kiste rasch findet, ist damit nicht die Erfahrung aller beschrieben.","id":47,"coreId":8,"reserveNo":2,"type":"multi","l":1,"c":1,"caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M3"]},{"title":"Warum es eilt","scene":"Sebastian Wolf möchte beiden Läden schnell antworten.","ask":"Welches Risiko nennt er?","options":["Bis Freitag sollen die Absatzmengen neu erhoben werden","Die Kundschaft könnte den Newsletter nur am Montag lesen","Die Läden haben Termine bereits an Global Bike vergeben","Die Lieferungen kommen erst in der nächsten Woche an","Christian wird die Vergleichsrechnung streichen","Die Läden könnten ihre Flächen inzwischen anders nutzen"],"answer":[5],"why":"Sebastian will die Flächen für eine mögliche Wiederholung sichern. Dafür ist eine schnelle Rückmeldung wichtig.","hint":"Suche den Grund, den Sebastian in seiner Aussage selbst nennt.","steps":"Notiere das Anliegen zu jeder Person. Verbinde beide Anliegen in der Planung.","example":"Bei einer knappen Frist kann ein Team zuerst Zwischenstand und Prüftermin mitteilen.","id":48,"coreId":9,"reserveNo":1,"type":"multi","l":1,"c":2,"caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["Handlungssituation"]},{"title":"Zwei Anliegen in einem Vorschlag verbinden","scene":"Übungsvariante: Im Gespräch liegen nur zwei Vorschläge vor: sofort verbindlich zusagen oder erst in mehreren Wochen zurückrufen.","ask":"Welcher dritte Weg berücksichtigt Sebastian und Christian?","options":["Die Flächen erst reservieren, wenn die nächste Aktion bereits ausgewertet ist","Christian entscheidet allein anhand der höheren Stückzahl","Die verbindliche Zusage kommt vor der Auswertung und kann später still geändert werden","Bis Freitag Rückmeldung geben und mögliche Termine zunächst nur als Vorschlag abstimmen","Nur dem Laden mit der besseren Rechnung antworten","Vor der endgültigen Zusage die Zielerreichung und Kundenhinweise beider Standorte prüfen"],"answer":[3,5],"why":"Eine zügige Rückmeldung gibt den Läden Planungssicherheit. Die Auswertung liefert die Begründung für eine verbindliche Folgeentscheidung.","hint":"Lass sowohl die Antwortfrist als auch die Prüfung der Belege stehen.","steps":"Notiere das Anliegen zu jeder Person. Verbinde beide Anliegen in der Planung.","example":"Bei einer knappen Frist kann ein Team zuerst Zwischenstand und Prüftermin mitteilen.","id":49,"coreId":9,"reserveNo":2,"type":"multi","l":1,"c":2,"caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["Handlungssituation"]},{"title":"Eine Spaltenüberschrift berichtigen","scene":"In einer Zeile für Block steht unter „Aktionsabsatz in €“ die Zahl 46.","ask":"Welche Überschrift passt zur eingetragenen Zahl?","options":["Umsatz in der Vergleichswoche in €","Zusätzlich verkaufte Stück","Durchschnitt je Öffnungstag in %","Verkaufte Stück in der Aktionswoche","Aktionsabsatz beider Läden in Stück","Prozentuale Veränderung gegenüber der Vergleichswoche"],"answer":[3],"why":"46 bezeichnet die Stückzahl des Aktionssortiments in der Aktionswoche bei Block.","hint":"Prüfe, in welcher Einheit der Absatzbericht rechnet.","steps":"Gib jeder Zahl einen Zeitraum und eine Einheit. Nenne den Bezugswert für das Urteil.","example":"Mit „30 Stück im Mai“ ist eine Zahl klarer als mit „30“.","id":50,"coreId":10,"reserveNo":1,"type":"multi","l":1,"c":4,"caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M5"]},{"title":"Zielprüfung auf einer Folie ermöglichen","scene":"Übungsvariante: Eine Folie zeigt für die Bike Arena bisher nur „75“ und darunter „erreicht“.","ask":"Welche Ergänzungen machen die Prüfung nachvollziehbar?","options":["Die 75 zugleich als Stückzahl und Prozentzahl verwenden","Den Zuwachs von 25 % mit dem Zielwert von 20 % vergleichen","Die gemeinsame Stückzahl beider Standorte als einzige Bezugsgröße eintragen","Die Stellungnahme der Ladenleitung statt der Vergleichswoche abdrucken","Den Umsatz als Eurobetrag aus dem Absatz schätzen","Die beiden Wochen mit 60 Stück und 75 Stück beschriften"],"answer":[1,5],"why":"Die Beschriftung gibt für 60 und 75 den Zeitraum und die Einheit an. Der Zielwert macht das Urteil überprüfbar.","hint":"Welche Ausgangszahl und welche Grenze fehlen den Lesenden?","steps":"Gib jeder Zahl einen Zeitraum und eine Einheit. Nenne den Bezugswert für das Urteil.","example":"Mit „30 Stück im Mai“ ist eine Zahl klarer als mit „30“.","id":51,"coreId":10,"reserveNo":2,"type":"multi","l":1,"c":4,"caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M5"]},{"title":"Aus einem Hinweis eine Frage machen","scene":"Eine Person bei der Bike Arena möchte wissen, für welche Ventile die Minipumpe passt.","ask":"Was stützt diese Rückmeldung unmittelbar?","options":["Alle Personen an der Gondel hatten dasselbe Ventil","Beim nächsten Termin werden durch diese Ergänzung mindestens 20 % mehr Pumpen verkauft","Die Rahmentasche müsste allein wegen der Pumpenfrage aus dem Regal genommen werden","Die Minipumpe darf an diesem Standort nicht mehr verkauft werden","Die Ventilangabe erklärt den gesamten bisherigen Mehrabsatz","Eine passende Ventilangabe hilft, die konkret gestellte Frage an der Gondel zu beantworten"],"answer":[5],"why":"Die Rückmeldung benennt eine fehlende Produktinformation. Welche Folgen eine ergänzte Karte für den Absatz hat, bleibt offen.","hint":"Verbinde die geäußerte Frage mit dem konkreten Informationsbedarf.","steps":"Verbinde zuerst die konkrete Beobachtung mit einer Maßnahme. Trenne davon die vermutete Wirkung.","example":"Eine fehlende Maßangabe ist ein Grund, die Angabe zu ergänzen. Ob sie Käufe erhöht, muss geprüft werden.","id":52,"coreId":11,"reserveNo":1,"type":"multi","l":1,"c":1,"caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M3","M5","M6"]},{"title":"Die Wirkung einer Änderung offenlassen","scene":"Übungsvariante: Nach der Wartesituation bei Block möchte das Team einen zusätzlichen Abstellplatz für das zweite Rad einrichten.","ask":"Welche Aussagen könnt ihr mit der bisherigen Rückmeldung begründen?","options":["Die Rückmeldung beweist, dass Block sein Absatzziel nach dem Umbau erreicht","Mit der neuen Stelle werden garantiert mehr Lichtsets verkauft","Der Vorschlag geht auf die gemeldete Enge im Durchgang ein","Alle Kundinnen und Kunden mussten vorher am Durchgang warten","Die Maßnahme ersetzt automatisch den Newsletter","Ob der Durchgang beim nächsten Termin tatsächlich häufiger frei bleibt, könnt ihr dann beobachten"],"answer":[2,5],"why":"Die gemeldete Enge ist ein Anlass für den Vorschlag. Die Wirkung des Umbaus muss in der nächsten Aktion beobachtet werden.","hint":"Unterscheide Anlass für eine Maßnahme und überprüfte Wirkung.","steps":"Verbinde zuerst die konkrete Beobachtung mit einer Maßnahme. Trenne davon die vermutete Wirkung.","example":"Eine fehlende Maßangabe ist ein Grund, die Angabe zu ergänzen. Ob sie Käufe erhöht, muss geprüft werden.","id":53,"coreId":11,"reserveNo":2,"type":"multi","l":1,"c":1,"caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M3","M5","M6"]},{"title":"Blocks fehlende Summe ergänzen","scene":"Für Blocks Vergleichswoche hast du schon 35 Stück für das Kernsortiment ermittelt. M2 nennt außerdem fünf verkaufte Sattelüberzüge R40.","ask":"Welcher Eintrag gehört in die vollständige Vergleichsspalte?","options":["30 verkaufte Stück","35 verkaufte Stück","5 verkaufte Stück","40 € Umsatz","40 verkaufte Stück","45 verkaufte Stück"],"answer":[4],"why":"35 Stück aus dem gemeinsamen Angebot plus 5 aus der lokalen Ergänzung ergeben 40 verkaufte Stück.","hint":"Prüfe, ob der Sattelüberzug zum Aktionssortiment zählt.","steps":"Schreibe die Einzelmengen untereinander. Berücksichtige auch die Artikel aus der lokalen Ergänzung.","example":"Vier gemeinsame Artikel ergeben zusammen 30 Stück. Drei lokale Stücke ergeben insgesamt 33.","id":54,"coreId":12,"reserveNo":1,"type":"multi","l":2,"c":3,"caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M2","M5"]},{"title":"Vergleichsabsatz bei sechs Artikeln","scene":"Übungsvariante: In der Vergleichswoche verkauft ein weiterer Laden 9 Lichtsets, 7 Schlösser, 6 Taschen und 12 Pumpen aus dem Kernsortiment. Als lokale Ergänzungen verkauft er 4 Flaschenhalter und 2 Reflektorbänder.","ask":"Welche Summenprüfung stimmt?","options":["Die beiden lokalen Ergänzungen zählen zusammen 12 Stück","40 Stück sind die Zunahme gegenüber der Aktionswoche","34 Stück sind die Gesamtmenge, weil zwei Artikel lokale Ergänzungen sind","Die vier zuerst genannten Artikel ergeben als Zwischensumme 34 Stück","Nur die ersten vier Waren ergeben 40 Stück","Alle sechs Artikel ergeben 40 Stück"],"answer":[3,5],"why":"9 + 7 + 6 + 12 ergeben 34. Die lokalen Ergänzungen bringen 6 Stück hinzu. Die Summe ist 40.","hint":"Bilde zunächst zwei Zwischensummen und addiere sie.","steps":"Schreibe die Einzelmengen untereinander. Berücksichtige auch die Artikel aus der lokalen Ergänzung.","example":"Vier gemeinsame Artikel ergeben zusammen 30 Stück. Drei lokale Stücke ergeben insgesamt 33.","id":55,"coreId":12,"reserveNo":2,"type":"multi","l":2,"c":3,"caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M2","M5"]},{"title":"Fehlende Stücke bis zum Ziel","scene":"Bei Block sind 40 Stück der Ausgangswert. Die Aktion bringt 46 Stück. Das Ziel liegt bei mindestens 20 % mehr Stück.","ask":"Welche Stückzahl hätte Block mindestens in der Aktionswoche verkaufen müssen?","options":["48 Stück","50 Stück","60 Stück","42 Stück","44 Stück","46 Stück"],"answer":[0],"why":"20 % von 40 sind 8. Mit 40 + 8 = 48 Stück wäre die Zielmarke erreicht.","hint":"Rechne den prozentualen Zuwachs erst in eine Stückzahl um.","steps":"Ermittle die erforderliche Zunahme oder den tatsächlichen Prozentwert. Vergleiche anschließend mit dem Ziel.","example":"Bei 50 Stück und einem Ziel von +10 % braucht der Laden 55 Stück.","id":56,"coreId":13,"reserveNo":1,"type":"multi","l":2,"c":3,"caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M2","M5"]},{"title":"Einen Anstieg trotz Zielverfehlung beschreiben","scene":"Übungsvariante: Ein Laden steigert sich von 50 auf 58 Stück und hat dasselbe 20-%-Ziel wie Block.","ask":"Welche Aussagen gehören in die Auswertung?","options":["Die Steigerung beträgt 8 %, weil acht Stück hinzugekommen sind","Der Laden erreicht 20 %, sobald mehr als 50 Stück verkauft werden","Der Laden verkauft 8 Stück mehr","Der Absatz wächst um 16 % und bleibt unter der Zielmarke","Der Laden verfehlt die Zielmarke um 8 Prozentpunkte","Der Laden hätte 58 Stück zum Erreichen der Zielmarke gebraucht"],"answer":[2,3],"why":"8 ÷ 50 × 100 ergibt 16 %. Für +20 % wären 60 Stück nötig.","hint":"Halte Steigerung in Stück und Steigerung in Prozent getrennt fest.","steps":"Ermittle die erforderliche Zunahme oder den tatsächlichen Prozentwert. Vergleiche anschließend mit dem Ziel.","example":"Bei 50 Stück und einem Ziel von +10 % braucht der Laden 55 Stück.","id":57,"coreId":13,"reserveNo":2,"type":"multi","l":2,"c":3,"caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M2","M5"]},{"title":"Die Zielmenge in Leer bestimmen","scene":"60 Stück waren der Vergleichswert der Bike Arena. Das gemeinsame Ziel beträgt je Laden +20 %. Tatsächlich verkauft die Bike Arena 75 Stück.","ask":"Welche Aussagen zur Zielmenge sind richtig?","options":["Die Zielmenge beträgt 80 Stück","Bei 72 verkauften Stücken wäre die Zielmarke erreicht","Die Zielmarke liegt bei 65 Stück","Die Bike Arena liegt mit 75 Stück um drei Stück über der Zielmenge","Die Zielmenge liegt drei Prozentpunkte über dem beobachteten Zuwachs","Die 75 Stück sind die Ausgangsmenge zur Berechnung"],"answer":[1,3],"why":"20 % von 60 sind 12. Die Zielmenge beträgt 72 Stück, der tatsächliche Absatz 75 Stück.","hint":"Addiere 20 % der Vergleichsmenge zur Vergleichsmenge.","steps":"Berechne aus der Vergleichsmenge die Mindestmenge. Miss daran die tatsächliche Aktionsmenge.","example":"Bei 20 Stück bedeutet ein Zuwachs um 5 Stück +25 %.","id":58,"coreId":14,"reserveNo":1,"type":"multi","l":2,"c":3,"caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M2","M5"]},{"title":"Erreicht oder übertroffen?","scene":"Übungsvariante: Ein Laden verkauft vorher 80 Stück, danach 100. Das Standortsoll liegt wie in Leer bei mindestens +20 %.","ask":"Welche Aussagen sind belastbar?","options":["Der Absatz liegt um 80 % über der Vergleichswoche","Das Ziel ist verfehlt, weil eine Verfünffachung gefordert ist","Der Zuwachs beträgt 25 %, das Ziel ist erfüllt","Bei 100 Stück als Bezugswert ergibt sich der vorgeschriebene Standortsvergleich","Die 20 zusätzlichen Stück entsprechen immer genau 20 %","Der Absatz liegt 20 Stück über der Vergleichswoche"],"answer":[2,5],"why":"20 ÷ 80 × 100 ergibt 25 %. Das sind 5 Prozentpunkte mehr als gefordert.","hint":"Rechne mit 80 Stück als Ausgangswert und vergleiche dann mit 20 %.","steps":"Berechne aus der Vergleichsmenge die Mindestmenge. Miss daran die tatsächliche Aktionsmenge.","example":"Bei 20 Stück bedeutet ein Zuwachs um 5 Stück +25 %.","id":59,"coreId":14,"reserveNo":2,"type":"multi","l":2,"c":3,"caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M2","M5"]},{"title":"Das Ziel gehört zu jeder Zeile","scene":"Der Gesamtwert für beide Läden ist +21 %. Für Block steht in der Standortzeile +15 %.","ask":"Welcher Eintrag passt unter „Ziel erreicht?“ bei Block?","options":["Nein, weil jeder Laden exakt 20 % erreichen muss","Offen, weil die Bike Arena mitgerechnet werden muss","Ja, weil 15 zusätzliche Stück die Zielmarke sind","Nein, weil Block unter 20 % liegt","Ja, weil beide Läden zusammen über 20 % liegen","Ja, weil der Absatz von Block gestiegen ist"],"answer":[3],"why":"Bei Block gilt der eigene Prozentwert. Der Gesamtwert darf das Standorturteil nicht ersetzen.","hint":"Lies den Zielwert in derselben Standortzeile wie das Ergebnis.","steps":"Prüfe Summen getrennt von Standortwerten. Verwende für die Zielentscheidung den passenden Wert.","example":"Ein Durchschnitt über zwei Standorte kann eine Schwäche an einem einzelnen Standort verdecken.","id":60,"coreId":15,"reserveNo":1,"type":"multi","l":2,"c":1,"caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M2","M5"]},{"title":"Ein Gesamtergebnis kritisch prüfen","scene":"Übungsvariante: Laden Nord steigt von 30 auf 45 Stück, Laden Süd von 70 auf 75. Zusammen sind das 100 auf 120 Stück. Ziel sind je Laden mindestens +20 %.","ask":"Welche Beurteilung kannst du verantworten?","options":["Keiner der Läden erfüllt das Ziel, weil das Ergebnis zusammen ausgeglichen werden muss","Beide haben ihr Einzelziel erfüllt, weil die Summe genau auf +20 % kommt","Laden Nord erfüllt das Ziel mit +50 %","Laden Süd erfüllt es, weil er 75 Stück verkauft und damit Nord übertrifft","Laden Süd wächst nur um rund 7 % und verfehlt sein Ziel","Das Gesamtergebnis darf nicht genannt werden, weil es mathematisch falsch ist"],"answer":[2,4],"why":"Nord: 15 ÷ 30 = 50 %. Süd: 5 ÷ 70 ≈ 7 %. Die Summe ist richtig, sagt aber nichts Sicheres über jedes Einzelziel aus.","hint":"Berechne die beiden Standortprozente vor dem Urteil.","steps":"Prüfe Summen getrennt von Standortwerten. Verwende für die Zielentscheidung den passenden Wert.","example":"Ein Durchschnitt über zwei Standorte kann eine Schwäche an einem einzelnen Standort verdecken.","id":61,"coreId":15,"reserveNo":2,"type":"multi","l":2,"c":1,"caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M2","M5"]},{"title":"Die Basis des Lichtsets","scene":"Beim LED-Lichtset in Leer steigen die verkauften Mengen von 10 auf 13. Im Entwurf steht „3 ÷ 13“.","ask":"Welche Fassung korrigiert die Rechnung?","options":["3 ÷ 13 × 100 ergibt rund 23 % Zuwachs","13 ÷ 10 × 100 ergibt 130 % Zuwachs","13 ÷ 3 × 100 ergibt 433 % Zuwachs","3 ÷ 10 × 100 ergibt 30 % Zuwachs","10 ÷ 13 × 100 ergibt 77 % Zuwachs","3 ÷ 100 × 10 ergibt 0,3 % Zuwachs"],"answer":[3],"why":"Der Zuwachs von 3 Stück wird am Ausgangswert von 10 gemessen.","hint":"Prüfe, welcher Wert vor der Aktion galt.","steps":"Bestimme die Differenz. Setze darunter die Vergleichsmenge und rechne in Prozent um.","example":"Von 25 auf 30 Stück: 5 ÷ 25 × 100 = 20 %.","id":62,"coreId":16,"reserveNo":1,"type":"multi","l":2,"c":3,"caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M5"]},{"title":"Korrektur mit Stück und Prozent","scene":"Übungsvariante: Ein Artikel fällt von 40 auf 34 Stück. Jemand trägt −17,6 % ein, weil er durch 34 teilt.","ask":"Welche Korrekturen stimmen?","options":["Die Differenz ist −6 Stück","Die Prozentänderung bleibt −17,6 %, weil nur der neue Wert zählt","Als Änderung gehören −6 ÷ 40 × 100 = −15 % in den Bericht","40 ÷ 34 × 100 beschreibt den Rückgang unmittelbar","Die Stückänderung beträgt +6","Die 34 Stück sind die passende Basis, weil sie die jüngste Zahl sind"],"answer":[0,2],"why":"Das Minus folgt aus 34 − 40. Der Vergleichswert 40 bleibt der Nenner.","hint":"Rechne zuerst neue Menge minus alte Menge und teile erst dann.","steps":"Bestimme die Differenz. Setze darunter die Vergleichsmenge und rechne in Prozent um.","example":"Von 25 auf 30 Stück: 5 ÷ 25 × 100 = 20 %.","id":63,"coreId":16,"reserveNo":2,"type":"multi","l":2,"c":3,"caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M5"]},{"title":"Den Durchgang freihalten","scene":"Eine Person bei Block wartet, weil gerade zwei Fahrräder am Beratungsplatz stehen.","ask":"Welche erste Änderung greift genau diesen Hinweis auf?","options":["Eine feste zweite Abstellstelle neben dem Beratungsplatz außerhalb des Durchgangs vorsehen","Die Anleitung zum Ventil auf das Eintrittsschild schreiben","Mehr Räder in den Durchgang stellen, damit die Kundschaft die Beratung erkennt","Den Newsletter später versenden","Die beiden Fahrräder vor der Kasse abstellen","Das Schloss durch einen Flaschenhalter ersetzen"],"answer":[0],"why":"Eine Abstellstelle neben dem Beratungsplatz kann den Durchgang bei der Vorführung freihalten.","hint":"Frage, wo das Hindernis entstanden ist.","steps":"Markiere die Stelle im Laden, an der das Problem auftritt. Suche eine passende Veränderung der Platzierung.","example":"Eine schlecht erreichbare Ware lässt sich tiefer hängen.","id":64,"coreId":17,"reserveNo":1,"type":"multi","l":2,"c":0,"caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M3","M5"]},{"title":"Eine neue Engstelle am Warenträger","scene":"Übungsvariante: Beim Folgetermin hängt Zubehör sehr hoch. Zwei Personen stellen sich beim Herunternehmen in denselben schmalen Durchgang.","ask":"Welche Änderungen könnt ihr aus dieser Beobachtung ableiten?","options":["Alle Artikel ohne Prüfung aus dem Sortiment entfernen","Die hohen Haken behalten und nur einen weiteren Newsletter verschicken","Häufig nachgefragtes Zubehör tiefer und gut erreichbar platzieren","Mehr Haken im selben engen Durchgang montieren","Das Probieren oder Entnehmen vom Hauptweg weg an einem geeigneten Platz anordnen","Den Absatz aus der Vergleichswoche korrigieren"],"answer":[2,4],"why":"Die Maßnahmen ändern den Zugriff und verlagern den Aufenthalt aus der Engstelle. Ob die neue Anordnung funktioniert, lässt sich danach beobachten.","hint":"Verbessere den Zugang zur Ware und den freien Laufweg.","steps":"Markiere die Stelle im Laden, an der das Problem auftritt. Suche eine passende Veränderung der Platzierung.","example":"Eine schlecht erreichbare Ware lässt sich tiefer hängen.","id":65,"coreId":17,"reserveNo":2,"type":"multi","l":2,"c":0,"caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M3","M5"]},{"title":"Ein Ventil-Schild prüfen","scene":"In der Bike Arena möchte eine Person an der Gondel erkennen, ob die Minipumpe zu ihrem Ventil passt.","ask":"Welcher Karteninhalt hilft ihr unmittelbar?","options":["Der Aktionstermin als einzige Angabe","Eine größere Abbildung des Ladenlogos","Die Gesamtzahl verkaufter Pumpen","Eine Liste der vom Hersteller angegebenen passenden Ventilarten","Die Artikelnummer des danebenliegenden Flaschenhalters","Ein allgemeiner Hinweis „Zubehör für jede Tour“"],"answer":[3],"why":"Die Käuferin oder der Käufer braucht eine nachprüfbare Kompatibilitätsangabe für die Pumpe.","hint":"Suche den Inhalt, der sich mit dem eigenen Ventil abgleichen lässt.","steps":"Bestimme, welche Frage die Kundschaft an der Ware beantworten will. Wähle Angaben, die direkt dazu passen.","example":"Eine Produktkarte kann die passenden Maße und eine Skizze zeigen.","id":66,"coreId":18,"reserveNo":1,"type":"multi","l":2,"c":4,"caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M3","M5"]},{"title":"Karten von mehreren Taschen vergleichen","scene":"Übungsvariante: An der Gondel liegen nun zwei Rahmentaschen. Kundinnen und Kunden sollen vor dem Kauf erkennen, welche zu ihrem Fahrrad passt.","ask":"Welche Ergänzungen erleichtern den Vergleich?","options":["Jedes Modell erhält eine andere Bezeichnung für dieselbe Maßangabe","Die größere Tasche erhält einfach den Aufdruck „für alle Rahmen“","Ein kleines Maßbild zeigt, wo man den Platz für die jeweilige Tasche nachmisst","Nur eine gemeinsame Preiszeile wird über beide Modelle gehängt","Die Karten nennen nur interne Lagernummern","Bei beiden Modellen stehen passende Rahmengrößen an derselben Stelle"],"answer":[2,5],"why":"Einheitliche Angaben und ein klarer Bezug zum Maß am Rad helfen, beide Modelle zuverlässig zu vergleichen.","hint":"Lege für beide Taschen dieselbe Frage und dieselbe Stelle auf den Karten fest.","steps":"Bestimme, welche Frage die Kundschaft an der Ware beantworten will. Wähle Angaben, die direkt dazu passen.","example":"Eine Produktkarte kann die passenden Maße und eine Skizze zeigen.","id":67,"coreId":18,"reserveNo":2,"type":"multi","l":2,"c":4,"caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M3","M5"]},{"title":"Wer wünscht welche Änderung?","scene":"Du hast zwei Ladenstimmen: „Den Kundenvergleich möchte ich einfacher machen“ und „Für die Beratung am Samstag wünsche ich mir einen besser nutzbaren Platz.“","ask":"Welche Zuordnung ist richtig?","options":["Beide Stimmen wünschen zuerst ein neues Werbemittel","Block will seine Vorführung durch zwei Gondeln ersetzen","Die Ladenleitung der Bike Arena fordert zunächst einen geänderten Newsletter","Die Bike Arena wünscht einen besseren Beratungsplatz und Block einfachere Produktkarten","Beide Stimmen stammen von Block","Die Bike Arena wünscht einen einfacheren Vergleich und Block einen besser nutzbaren Beratungsplatz"],"answer":[5],"why":"Die Bike Arena setzt auf Selbstbedienung und Vergleich. Block möchte den Platz für Beratung und Vorführung verbessern.","hint":"Achte darauf, welche Arbeitsweise der jeweilige Laden schon nutzt.","steps":"Notiere die Interessen beider Ladenleitungen getrennt. Prüfe, welche Maßnahme zu welchem Interesse passt.","example":"Ein gemeinsames Angebot kann zugleich auf zwei unterschiedlich eingerichteten Flächen stehen.","id":68,"coreId":19,"reserveNo":1,"type":"multi","l":2,"c":2,"caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M3","M5"]},{"title":"Einen Kompromiss vorbereiten","scene":"Übungsvariante: Block möchte die Vorführung behalten. Die Bike Arena möchte Kundinnen und Kunden weiterhin selbst vergleichen lassen. Global Bike kann das gemeinsame Kernangebot beibehalten.","ask":"Welche Vorschläge greifen die Wünsche gemeinsam auf?","options":["Beide verzichten auf ihre bisherige Präsentation und verteilen alles an der Kasse","Alle beraten künftig am selben Typ Beratungsplatz","Das gemeinsame Kernsortiment bleibt und der Beratungsplatz bei Block wird angepasst","Beide übernehmen dieselbe Selbstbedienungsfläche","Die Kundschaft erhält nur in Aurich Zubehör aus dem Kernsortiment","Die Bike Arena behält die freie Auswahl an der Gondel und erhält besser vergleichbare Karten"],"answer":[2,5],"why":"Ein gemeinsames Sortiment lässt sich vor Ort unterschiedlich präsentieren. Beide Arbeitsweisen bleiben in der Empfehlung berücksichtigt.","hint":"Trenne das gemeinsame Warenangebot vom Wunsch jedes einzelnen Ladens.","steps":"Notiere die Interessen beider Ladenleitungen getrennt. Prüfe, welche Maßnahme zu welchem Interesse passt.","example":"Ein gemeinsames Angebot kann zugleich auf zwei unterschiedlich eingerichteten Flächen stehen.","id":69,"coreId":19,"reserveNo":2,"type":"multi","l":2,"c":2,"caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M3","M5"]},{"title":"Werbewirkung oder Absatzentwicklung?","scene":"Bei Block zeigt M2 einen Anstieg von 40 auf 46 Stück. Eine Person kam laut M3 wegen der im Newsletter angekündigten Lichtvorführung.","ask":"Welche Formulierung gibt beides sauber wieder?","options":["Der Newsletter bewirkte erwiesenermaßen alle sechs zusätzlichen Verkäufe","Fast alle Personen kamen wegen des Newsletters","Der Newsletter erhöhte den Absatz genau um 15 Prozentpunkte","Block verkaufte sechs Stück mehr und eine Person nennt den Newsletter als Besuchsgrund","Wegen der Rückmeldung wurden bei Block insgesamt sechs Lichtsets verkauft","M2 erfasst nur Verkäufe an Menschen, die den Newsletter gelesen hatten"],"answer":[3],"why":"M2 enthält Stückzahlen. M3 enthält eine einzelne Erklärung für einen Besuch. Welche Maßnahme den Anstieg verursacht hat, ist damit offen.","hint":"Nenne beide Belege getrennt und lass Ursache und Wirkung offen.","steps":"Schreibe die gemessene Veränderung und die Kundenrückmeldung in zwei getrennte Sätze.","example":"Die Menge steigt. Eine Person lobt ein Plakat. Keiner der beiden Sätze belegt den Anteil des Plakats am Zuwachs.","id":70,"coreId":20,"reserveNo":1,"type":"multi","l":2,"c":1,"caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M3","M5"]},{"title":"Zwei Veränderungen gleichzeitig","scene":"Übungsvariante: Ein Laden verschickt einen Newsletter und rückt Zubehör näher zum Eingang. Der Absatz steigt von 50 auf 60 Stück. Eine Person berichtet, dass sie zufällig am Regal vorbeiging.","ask":"Welche Aussagen sind belastbar?","options":["Ohne Newsletter wäre der Absatz unverändert gewesen","Eine Person nennt die Situation am Regal, ihr Beispiel erklärt den gesamten Zuwachs nicht","Die Lage des Regals hat sich beim Test als unwirksam erwiesen","Die Auswertung zeigt, welcher Werbekanal alle zehn Zusatzverkäufe ausgelöst hat","Der Newsletter verursacht die vollen 20 % Zuwachs","Die verkaufte Menge steigt um 20 %"],"answer":[1,5],"why":"Zwei Dinge wurden zugleich geändert. Stückzahlen und eine Einzelstimme erlauben keine eindeutige Zuordnung des Zuwachses.","hint":"Der Vergleich zeigt die Änderung der Menge, getrennt davon steht der Bericht einer Person.","steps":"Schreibe die gemessene Veränderung und die Kundenrückmeldung in zwei getrennte Sätze.","example":"Die Menge steigt. Eine Person lobt ein Plakat. Keiner der beiden Sätze belegt den Anteil des Plakats am Zuwachs.","id":71,"coreId":20,"reserveNo":2,"type":"multi","l":2,"c":1,"caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M3","M5"]},{"title":"Einen lokalen Artikel beobachten","scene":"In Leer steigt der Absatz des Flaschenhalters F60 von 8 auf 10 Stück. F60 ist dort eine lokale Ergänzung.","ask":"Welche Empfehlung stützt diese Angabe für den nächsten Termin?","options":["Aus dem Anstieg folgt, dass nur das Eingangsschild erfolgreich war","F60 durch R40 ersetzen, weil Aurich mehr verkauft hat","Alle lokalen Artikel sind allein wegen des Halters überflüssig","F60 in beiden Läden sofort zum Pflichtartikel machen","F60 streichen, weil acht Stück zu wenig waren","F60 in Leer zunächst beibehalten und den Absatz wieder getrennt erfassen"],"answer":[5],"why":"Die zwei zusätzlichen Stück sind ein Hinweis für Leer. Eine erneute getrennte Erfassung zeigt, ob sich der Absatz beim nächsten Termin bestätigt.","hint":"Unterscheide eine vorläufige Entscheidung für den Ort von einer allgemeinen Regel.","steps":"Leite einen Test aus den vorhandenen Hinweisen ab. Lege fest, was du beim nächsten Mal dafür erfasst.","example":"Ein Artikel, den jemand spät entdeckt hat, kann zunächst einen sichtbareren Platz bekommen.","id":72,"coreId":21,"reserveNo":1,"type":"multi","l":2,"c":0,"caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M3","M5"]},{"title":"Zusatz im Sortiment behalten oder tauschen?","scene":"Übungsvariante: Ein weiterer Laden führt in der Vergleichs- und der Aktionswoche eine Klingel als lokale Ergänzung. In jeder Woche verkauft er sechs Klingeln. Eine Kundin bemerkt die Klingel erst, nachdem sie bezahlt hat.","ask":"Welche nächsten Schritte sind für die Klingel begründbar?","options":["Aus der Kundenstimme eine genaue Prognose von 12 Stück für die Folgewoche ableiten","Die Klingel in alle Filialen aufnehmen, weil sich ihr Absatz stark erhöht hat","Die Klingel vorerst behalten und neben gut sichtbares Zubehör stellen","Die Klingel wegen der jeweils sechs verkauften Exemplare sofort aus dem Angebot nehmen","Beim neuen Platz erfassen, ob die Klingel früher auffällt und wie viele Stück verkauft werden","Nur den Preis aller Kernartikel senken"],"answer":[2,4],"why":"Die Sichtbarkeit ist ein Ansatzpunkt aus dem Fall. Die gleiche Stückzahl zeigt allein weder hohe noch niedrige Eignung für die Aktion.","hint":"Prüfe zuerst ein konkretes Platzierungsproblem, bevor du aus sechs Verkäufen weitergehende Schlüsse ziehst.","steps":"Leite einen Test aus den vorhandenen Hinweisen ab. Lege fest, was du beim nächsten Mal dafür erfasst.","example":"Ein Artikel, den jemand spät entdeckt hat, kann zunächst einen sichtbareren Platz bekommen.","id":73,"coreId":21,"reserveNo":2,"type":"multi","l":2,"c":0,"caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M3","M5"]},{"title":"Kernaussage für die Bike Arena","scene":"Die Kurzvorlage soll Menge, Prozentwert und Zielurteil für Leer in einem Satz nennen.","ask":"Welcher Satz ist ganz richtig?","options":["Leer verkauft 60 Stück während der Aktion und erreicht +25 %","Leer steigt von 60 auf 75 Stück und verfehlt das Ziel","Leer legt um 15 % zu und übertrifft das 20-%-Ziel","Leer steigt von 60 auf 75 Stück, also um 25 %, und erreicht das Ziel","Leer erzielt 75 € Umsatz und erreicht +25 Stück","Beide Läden zusammen ergeben 75 Stück, also ist Leers Ziel erreicht"],"answer":[3],"why":"Die Aktionswoche umfasst 75 Stück, die Vergleichswoche 60. Die 15 zusätzlichen Stück entsprechen 25 %.","hint":"Prüfe Standort, Wochen, Einheit und Zielaussage im selben Satz.","steps":"Prüfe für jede Meldung die Zuordnung von Standort und Zahlen. Ergänze einen konkreten Beleg zur Maßnahme.","example":"Ein Wert von +8 % mit Ziel +15 % ergibt eine klare Zeile mit dem Urteil „Ziel verfehlt“.","id":74,"coreId":22,"reserveNo":1,"type":"multi","l":2,"c":4,"caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M3","M5"]},{"title":"Einen Folgebericht kürzen","scene":"Übungsvariante: Jan bekommt nur eine Folie. Er will zuerst wissen, wo eine Korrektur nötig ist und welcher Kundeneinwand dahin führt.","ask":"Welche Angaben sollten in der Kurzvorlage stehen?","options":["Leer verfehlt die Grenze, die Warenmenge der Aktionswoche war 60 Stück","Leer erreicht +25 %, passende Ventilarten auf der Pumpenkarte würden die konkrete Kundenfrage beantworten","Der Absatz beider Läden steigt zusammen, deshalb ist keine Anpassung erforderlich","Newsletter und Schild verdoppelten nachweislich den Absatz bei beiden Standorten","Block erreicht +25 % und sollte daher die Aktionsgondeln ausbauen","Block bleibt mit +15 % unter der Marke, für die Vorführung soll der Durchgang besser freigehalten werden"],"answer":[1,5],"why":"Die Vorlagenzeile je Standort verbindet ein korrektes Zielurteil mit einer belegten Änderung. Der Standort bleibt eindeutig.","hint":"Zu welcher Stelle passt die Kundenfrage, und welchen Prozentwert hat genau dieser Laden?","steps":"Prüfe für jede Meldung die Zuordnung von Standort und Zahlen. Ergänze einen konkreten Beleg zur Maßnahme.","example":"Ein Wert von +8 % mit Ziel +15 % ergibt eine klare Zeile mit dem Urteil „Ziel verfehlt“.","id":75,"coreId":22,"reserveNo":2,"type":"multi","l":2,"c":4,"caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M3","M5"]},{"title":"Den neuen Laden kennenlernen","scene":"Der Zweiradladen Aurich hat laut Fall Verkauf und Werkstatt. Ihr prüft jetzt, welche Form der Aktion zu ihm passt.","ask":"Welche Frage beantwortet zuerst einen wichtigen Punkt für die Umsetzung?","options":["Wie viele Räder wurden im gesamten Landkreis vor zehn Jahren verkauft?","Wie können wir Blocks Newsletter ohne Rücksprache versenden?","Kann man aus Leers hoher Stückzahl den Umsatz in Aurich berechnen?","Wird die nächste Aktionswoche genau 75 Stück bringen?","Hat der Laden zufällig die gleichen Farben wie die Bike Arena?","Welche Zubehörwaren fragen die Kundinnen und Kunden nach?"],"answer":[5],"why":"Die Nachfrage vor Ort hilft, ein passendes Angebot zu wählen. Die Zahlen anderer Läden sind nur Vergleichshinweise.","hint":"Frage nach einer Information, die das Angebot für den neuen Standort unmittelbar beeinflusst.","steps":"Sammle Angaben aus dem neuen Laden. Prüfe danach, welche Teile der Aktion dort machbar sind.","example":"Für eine Vorführung braucht ein Geschäft Platz und Zeit für Beratung.","id":76,"coreId":23,"reserveNo":1,"type":"multi","l":2,"c":2,"caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["Handlungssituation"]},{"title":"Eine kleine Fläche sinnvoll prüfen","scene":"Übungsvariante: Ein neuer Laden hat wenig freien Platz im Verkaufsraum und kann Vorführungen nur mit einem Mitarbeitenden anbieten. Ein Partner will beide großen Aktionsgondeln aus Leer übernehmen.","ask":"Welche Informationen solltest du vor der Empfehlung einholen?","options":["Ob man den Termin sofort bestätigen kann, damit keine Rückfragen mehr entstehen","Ob der Absatz in Leer hoch genug war, um die Gondeln überall zu nutzen","Wie viel nutzbare Fläche und welcher freie Laufweg im Laden tatsächlich bleiben","Welche Hälfte der Kundschaft von Block ihre Sattelüberzüge bezahlt hat","Wann und mit welchem Personal kurze Vorführungen möglich wären","Ob alle Werbemittel aus Leer dasselbe Firmenlogo zeigen"],"answer":[2,4],"why":"Fläche und Personal beeinflussen, was vor Ort umsetzbar ist. Diese beiden Bedingungen müssen vor der Empfehlung geklärt werden.","hint":"Übertrage die Idee auf den neuen Laden, indem du zuerst dessen Rahmen prüfst.","steps":"Sammle Angaben aus dem neuen Laden. Prüfe danach, welche Teile der Aktion dort machbar sind.","example":"Für eine Vorführung braucht ein Geschäft Platz und Zeit für Beratung.","id":77,"coreId":23,"reserveNo":2,"type":"multi","l":2,"c":2,"caseLabel":"LS 6.8 · Über die Fortführung der Aktion entscheiden","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["Handlungssituation"]}];
